package com.casetracker.ui.law

val LF2_HEFEI_ROAD_SAFETY: LawBook = LawBook(
    id = "hefei_road_safety",
    name = "合肥市道路交通安全条例",
    articlesCount = 68,
    chapters = 7,
    intro = """2009年通过，2013年修订，2014年1月1日施行。合肥市道路交通安全地方性法规，全文收录（共68条）。来源：合肥市人大常委会。""",
    articles = listOf(
        LawArticle("第一条", "", """为维护道路交通秩序，预防和减少交通事故，提高道路通行效率，根据《中华人民共和国道路交通安全法》、《中华人民共和国道路交通安全法实施条例》、《安徽省实施〈中华人民共和国道路交通安全法〉办法》等法律、法规，结合本市实际，制定本条例。"""),
        LawArticle("第二条", "", """本市行政区域内的车辆驾驶人、行人、乘车人以及与道路交通活动有关的单位和个人，应当遵守本条例。"""),
        LawArticle("第三条", "", """市、县（市）区人民政府及其有关部门应当建立道路交通安全协调机制，实行道路交通安全防范责任制和交通事故责任追究制，认真履行社会化管理职责。市、县（市）区人民政府及其有关部门，应当将道路交通安全事故隐患治理、道路交通事故社会救助、道路交通安全宣传教育及道路智能交通建设、道路交通安全设施建设纳入道路交通安全管理规划，所需经费应当纳入同级财政预算。开发区管理机构应当按照本条例规定做好道路交通安全工作。"""),
        LawArticle("第四条", "", """市、县（市）区人民政府公安机关交通管理部门以及相当于同级的公安机关交通管理部门负责本辖区内的道路交通安全管理工作。安全生产、交通、规划、环保、城市管理、园林、教育、农业（农业机械）、卫生、质量技术监督、工商等相关职能部门以及高速公路建设和管理部门应当依据各自职责，做好道路交通安全的相关工作。"""),
        LawArticle("第五条", "", """市、县（市）区人民政府可以聘用道路交通安全协管员，协助交通警察维护道路交通秩序。鼓励单位和个人进行道路交通安全志愿服务，协助交通警察维护道路交通秩序，宣传道路交通安全法律、法规。"""),
        LawArticle("第六条", "", """新闻、出版、广播、电视等有关单位和媒体，应当加强道路交通安全法律、法规的宣传，播发道路交通安全管理信息，引导公众积极维护交通安全。公安机关交通管理部门应当通过互联网、新闻媒体等途径公告道路交通安全管理措施，提供道路交通安全咨询，发布相关道路交通安全信息。"""),
        LawArticle("第七条", "", """机动车排放污染物应当符合国家和地方机动车污染物排放标准，不符合机动车污染物排放标准的车辆，不得核发环保检验合格标志，公安机关交通管理部门不予办理相应登记手续。机动车环保检验合格标志应当粘贴在前方挡风玻璃内侧右上角。"""),
        LawArticle("第八条", "", """依法应当登记的非机动车，车主应当自购车之日起三十日之内携带有效证明及车辆到公安机关交通管理部门办理有关登记手续。未依法登记的，不得上道路行驶。法律、法规另有规定的除外。"""),
        LawArticle("第九条", "", """禁止单位和个人生产、销售非标准车。本条例实施前非标准车已办理临时通行标志的，在准许通行的有效期限内，可以上道路行驶；上道路行驶时，应当随车携带临时通行证，并遵守机动车通行有关规定；同方向划有两条以上机动车道的，应当在最右侧车道行驶。非标准车不得载人；载物时，按照非机动车载物规定执行。"""),
        LawArticle("第十条", "", """市区停止办理摩托车注册登记，但因公务需要的除外。市区以外注册登记的摩托车不得迁入市区登记。市人民政府根据道路交通安全状况，可以对摩托车的通行采取限制措施，具体管理办法另行制定。"""),
        LawArticle("第十一条", "", """从事运输建筑垃圾和预拌混凝土等的车辆应当按照公安机关交通管理部门的规定，在驾驶室顶部、车身或者车厢后部、侧面等部位喷涂、悬挂放大号牌。城市管理部门核定运送建筑垃圾车辆的行驶路线、时间，应当征求公安机关交通管理部门的意见。"""),
        LawArticle("第十二条", "", """车辆号牌、临时通行标志应当悬挂在规定的位置，不得故意遮挡、污损，并保持端正、清晰、完整，禁止涂描、倒置、折叠、重叠或者有其他妨碍号牌识别的行为。禁止安装、使用可变式号牌或者其他影响交通技术监控设备识别的装置。禁止在机动车上安装、使用影响交通技术监控设备正常使用的装置。"""),
        LawArticle("第十三条", "", """从事机动车租赁业务的单位，应当将车辆信息报送公安机关交通管理部门备案；签订租赁合同前，应当核对机动车承租人的身份信息和驾驶资格，不得将机动车租赁给无驾驶资格的人驾驶。"""),
        LawArticle("第十四条", "", """单位和个人不得有下列行为：（一）擅自改变机动车和非机动车已登记的结构、构造；（二）改动、拆除电动自行车限速装置或者对人力三轮车、自行车加装动力装置；（三）伪造、变造或者使用伪造、变造的非机动车号牌或者非机动车登记证、非标准车的临时通行标志或者临时通行证；（四）使用其他车辆的号牌、非机动车登记证、临时通行标志或者临时通行证；（五）驾驶设置电子广告装置或者其他影响安全驾驶标识的机动车在道路上行驶；（六）在车辆上加装射灯、遮阳伞等影响交通安全的设备。前款第五项所规定的具体内容由公安机关交通管理部门会同城市管理等部门另行制定。"""),
        LawArticle("第十五条", "", """驾驶人驾驶车辆上道路行驶前，应当对车辆的安全技术性能和车辆号牌以及放大号码进行检查；不得驾驶安全设施不全、机件不符合技术标准或者有妨碍号牌和放大号码识别情形的车辆上道路行驶。"""),
        LawArticle("第十六条", "", """公安机关交通管理部门和农业（农业机械）主管部门应当建立拖拉机、变型拖拉机以及驾驶人的登记、检验、考试、发证、交通违法和交通事故处理等信息共享机制。农业（农业机械）主管部门在办理拖拉机、变型拖拉机以及驾驶人业务时，应当核查交通违法和交通事故处理等相关信息，对于有交通违法行为和交通事故未处理完毕的，不得办理相应的登记、检验等手续。"""),
        LawArticle("第十七条", "", """机动车驾驶人联系方式和机动车所有人姓名、单位名称、住址、联系方式等信息变更的，应当在变更后三十日内向公安机关交通管理部门备案。"""),
        LawArticle("第十八条", "", """新建、改建、扩建城市道路，应当同步规划、设计智能交通项目、监控设备、交通信号灯、标志、标线等交通安全设施，并与道路建设主体工程同步施工。交通安全设施未经验收或者验收不合格的，不得投入使用。城市道路以及道路配套设施的规划、设计、建设和竣工验收，应当征求公安机关交通管理部门的意见。城市停车场（库）的规划和建设应当符合道路通行条件，适应车辆停放需求。鼓励单位停车场（库）向社会开放。"""),
        LawArticle("第十九条", "", """在交通事故多发或者存在严重交通安全隐患的路段，道路管理养护部门应当会同公安机关交通管理部门设置警告标志、减速或者防护设施。公安机关交通管理部门发现已投入使用的道路和配套设施等存在交通安全隐患的，应当及时会同安全生产监督部门向有关责任主体单位提出整改意见；必要时向当地人民政府报告，当地人民政府应当及时作出处理决定。"""),
        LawArticle("第二十条", "", """道路两侧及隔离带上设置的管线、照明、广告牌等设施以及种植的植物不得影响道路交通安全，出现损坏或者照明不足，遮挡路灯、交通信号灯、交通标志等妨碍安全视距、影响道路交通安全情形的，交通、建设、电力、城市管理、绿化、通讯、市政等相关单位应当及时进行修复或者排除。"""),
        LawArticle("第二十一条", "", """单位和个人不得占用道路打谷、晾晒物品、堆物作业和其他妨碍道路交通安全的活动。禁止在道路交通安全设施上晾晒物品。"""),
        LawArticle("第二十二条", "", """因工程建设需要占用、挖掘道路，应当事先征得道路主管部门的同意；影响交通安全和通行的，应当征得公安机关交通管理部门的同意。施工单位应当在施工路段两端按照相关标准设置安全警示标志和安全防护设施。需要车辆绕行的，应当在绕行处设置标志。施工完毕应当及时清除道路上的障碍物，消除安全隐患，经道路主管部门和公安机关交通管理部门验收合格，方可恢复通行。"""),
        LawArticle("第二十三条", "", """道路作业单位在道路上进行维修、养护、保洁、绿化等作业时，应当采取必要的交通安全防护措施。作业人员应当穿着醒目的安全防护服装，使用喷涂或者粘贴有醒目反光材料的车辆。道路作业单位在高架道路、立交桥、下穿道路等特殊路段进行作业的，应当按照公安机关交通管理部门同意的方案进行作业。救援车辆在进行救援作业时，应当按照法律、法规关于事故现场的规定在现场设置安全警告标志。"""),
        LawArticle("第二十四条", "", """开辟、调整公共汽车、长途汽车的行驶路线和站点，建设、交通部门应当会同公安机关交通管理部门按照安全、畅通的要求确定。"""),
        LawArticle("第二十五条", "", """公安机关交通管理部门根据道路条件和通行需要，可以按照车型划分车道，并设置车道标志、标线。车辆应当按照规定的车道行驶，不得骑跨道路中心线、车道分隔线行驶,不得任意掉头。"""),
        LawArticle("第二十六条", "", """车辆、行人在辅道内或进出辅道时，应当按照交通信号通行；辅道未设置信号灯的，应当按照主道的信号灯通行。"""),
        LawArticle("第二十七条", "", """车辆进出村庄、住宅区、学校、机关、工厂和其他企事业单位时，应当让在道路上的行人、正常行驶的车辆优先通行。"""),
        LawArticle("第二十八条", "", """在设置公交专用车道的路段，公共汽车应当在专用车道内行驶；遇到转弯或者遇有障碍时，可以临时借用其他车道，转弯或者超越障碍后须及时驶回公交专用车道。公交专用车道仅供公共汽车、校车通行，其他车辆不得在公交专用车道内行驶；执行紧急任务的警车、消防车、救护车、工程救险车等特种车辆，可以借用公交专用车道行驶；遇特殊情况时，其他车辆可以在交通警察的指挥下借用公交专用车道行驶。"""),
        LawArticle("第二十九条", "", """机动车通过有方向指示信号灯并设置转弯待行区的交叉路口时，应当根据信号指示依次进入待行区停车等候。"""),
        LawArticle("第三十条", "", """车辆驾驶人应当遵守下列规定：（一）不得转借或者使用他人机动车驾驶证；（二）听从交通警察的指令，接受检查，不得驾车驶离现场；（三）不得有吸烟、饮食、穿着拖鞋、拨打接听手持电话、查看手机信息、观看电视、视频以及其他妨碍安全驾驶的行为；（四）机动车确需借用非机动车道、人行道行驶的，时速应低于二十公里，并确保安全；（五）不得用非牵引车牵引货运用途的挂车；（六）不得用全挂车、载运危险物品的机动车牵引故障机动车；（七）不得用摩托车、非标准车和电动自行车牵引、助推其他车辆；（八）携带儿童时应当使用与其年龄相适应的儿童安全座椅；（九）单位接送职工上下班的机动车辆，应当在公安机关交通管理部门指定的地点停靠；（十）叉车、轮式专用机械车上道路，应当按照公安机关交通管理部门指定的时间和路线行驶；（十一）机动车等待通行信号或者前方受阻临时停车时，不得允许乘车人上下车辆；（十二）不得在城市禁鸣区域内鸣喇叭；（十三）主动避让校车和执行任务的警车、消防车、救护车、工程救险车，不得有阻碍、穿插、尾追等行为；（十四）夜间在有路灯照明的城市道路上行驶时，不得使用远光灯，但遇有雨雾等恶劣气象条件的除外。"""),
        LawArticle("第三十一条", "", """车辆通行应当遵守以下规定：（一）特型机动车、重型和中型载货汽车、重型和中型专项作业车、重型和中型全挂以及半挂车、轮式专用机械车、低速载货汽车、三轮汽车、拖拉机、变型拖拉机以及运输危险物品的车辆不得进入市区二环路以内（不含二环路）道路行驶；（二）外地大型载客汽车以及市区以外的摩托车、取得市区以外临时通行标志的非标准车不得进入市区二环路以内（不含二环路）以及其他限行区域内的道路行驶；（三）本市大型和中型载客汽车、外地中型载客汽车不得进入市区一环路以内（含一环路）以及其他限行区域内的道路行驶；（四）载货汽车不得进入市区一环路以内（含一环路）道路行驶；（五）人力平板车、人力三轮车不得进入市区一环路以内（含一环路）道路行驶。禁止正三轮摩托车、畜力车在市区道路上行驶；除驾驭人外畜力车在其他道路上行驶时不得载人。上述车辆因特殊情况确需通行的，应当经市公安机关交通管理部门同意，并按照指定的时间和路线行驶。"""),
        LawArticle("第三十二条", "", """高架道路和上跨式立交桥，禁止行人和下列车辆通行：（一）摩托车、非标准车、残疾人机动轮椅车、电动自行车、自行车以及其他非机动车；（二）特型机动车、重型和中型专项作业车、轮式专用机械车以及运输危险物品的车辆；（三）拖拉机、变型拖拉机；（四）货运车辆、大型客运车辆；（五）悬挂试验车临时号牌的车辆。公共汽车、单位交通车以及从事高架道路和立交桥养护、维修、保洁作业的专用机动车除外。"""),
        LawArticle("第三十三条", "", """公安机关交通管理部门可以根据道路交通状况，确定限制通行的车辆和区域，并向社会公告；因大气污染防治需要，对取得黄色环保检验合格标志和未取得环保检验合格标志的机动车采取限制通行、禁止通行措施的，应当会同环境保护行政主管部门商定。"""),
        LawArticle("第三十四条", "", """在高架道路、立交桥桥面或者下穿道路行驶时，不得倒车或者停车。机动车在高架道路、立交桥或者下穿道路发生故障的，驾驶人应当将机动车移至道路右侧车道或者就近驶离；暂时无法移动的，应当立即开启危险报警闪光灯，设置警告标志，请求救援车、清障车对故障车辆进行拖曳、牵引，必要时迅速报警，车上人员不得在车道内活动或者逗留。"""),
        LawArticle("第三十五条", "", """公共汽车应当按照规定的路线行驶，在规定的站点距路沿五十厘米以内停靠，上下乘客后立即驶离。因特殊情况需要临时调整行驶路线、站点的，有关部门应当会同公安机关交通管理部门商定并及时公告。多辆公共汽车同时进入同一个站点停靠的，应当依次进站，并按照停靠的先后顺序依次离站。"""),
        LawArticle("第三十六条", "", """出租车应当按照规定停车，上下乘客时应当停靠在距路沿五十厘米以内。在设有定点停车处的路段，应当在定点停车处停靠，上下乘客后立即驶离。定点停靠的路段和定点停车处由公安机关交通管理部门统一划定，并向社会公布。其他各类营运车辆不得在停车场、站以外的城市道路上停车上下乘客或者等客。"""),
        LawArticle("第三十七条", "", """非机动车辆通过有交通信号控制的交叉路口，应当按照交通信号灯和交通标志、标线指示行驶，遇有停车信号时，应当停车等候，不得从路口外绕行。非机动车不得在未设置非机动车道的下穿道路通行。在公安机关交通管理部门允许通行非机动车的人行道上行驶时，应当避让行人。非下肢残疾人不得驾驶残疾人机动轮椅车。自行车、电动自行车在城市道路上行驶时可以限带十二周岁以下未成年人一人。其他非机动车在城市道路上行驶时不得带人。"""),
        LawArticle("第三十八条", "", """行人或者乘车人应当遵守下列规定：（一）不得移动、钻爬、跨越、倚坐道路隔离设施；（二）不得在车行道上停留、乞讨、兜售物品、散发宣传品以及有其他妨碍道路交通安全的行为；（三）不得在禁止停车的路段和逆行方向的道路一侧拦乘车辆；（四）不得在未设置人行道的下穿道路通行；（五）妥善看管携带的宠物或者其他动物，不得妨碍交通；（六）不得乘坐明知驾驶人未取得驾驶证或者饮酒后驾驶的机动车。"""),
        LawArticle("第三十九条", "", """单位或者个人不得指使、强迫、教唆他人在饮酒或者服用国家管制的精神药品、麻醉药品后驾驶机动车。"""),
        LawArticle("第四十条", "", """公安机关交通管理部门应当每年对学校、企业等有关单位开展道路交通安全法律法规等方面的宣传教育。国家机关、社会团体、企业事业单位和其他社会组织，应当做好本单位人员的交通安全教育和车辆管理工作，建立健全内部交通安全责任制。"""),
        LawArticle("第四十一条", "", """市、县（市）区人民政府及其有关部门应当按照预防和减少交通事故，保证道路交通安全、畅通的原则，制定应对自然灾害、恶劣气象条件、环境污染以及其他影响道路交通安全的突发事件的应急预案。公安、安全生产、交通、环保、卫生以及其他相关部门应当根据应急预案制定本部门的具体实施方案。遇有应急预案所规定的情形发生时，各有关部门应当立即启动应急预案，及时沟通、反馈信息，密切配合。"""),
        LawArticle("第四十二条", "", """因管理不善，饲养的动物造成道路交通事故的，由动物饲养人或者管理人承担事故责任；其他当事人有过错的，应当承担相应责任。"""),
        LawArticle("第四十三条", "", """道路交通事故当事人无正当理由不到公安机关交通管理部门接受事故调查的，公安机关交通管理部门应当在道路交通事故认定书中注明。其他当事人可以持道路交通事故认定书，就损害赔偿问题向人民法院提起民事诉讼。"""),
        LawArticle("第四十四条", "", """发生交通事故后，车辆驾驶人有下列行为之一的，应当承担全部责任，法律、法规另有规定的除外：（一）报案后无正当理由离开现场的；（二）送伤者到医院后逃匿的；（三）发生交通事故后，虽未离开现场，但不承认是交通事故车辆驾驶人，或者找人冒名顶替的；（四）交通事故发生后，对于相关事宜未能协商达成一致，或者虽经协商但给付的赔偿费用明显不足，未留下本人有效信息离开现场的。"""),
        LawArticle("第四十五条", "", """公安机关交通管理部门应当建立举报交通肇事逃逸事故奖励制度。对于举报属实的，给予举报人奖励，并为举报人保密。"""),
        LawArticle("第四十六条", "", """本市行政区域内发生的轻微交通事故，按照市公安机关交通管理部门的规定实行快速处置。"""),
        LawArticle("第四十七条", "", """公安机关交通管理部门对于道路交通安全违法行为应当及时纠正，并依法予以处罚；对于违法行为情节轻微，违法行为人愿意进行道路交通安全志愿服务，或者协助交通警察维护道路交通秩序、宣传道路交通安全法律法规的，可以免予罚款处罚，法律、法规另有规定的除外。"""),
        LawArticle("第四十八条", "", """违反本条例第七条第二款规定，未粘贴机动车环保检验合格标志的，由公安机关交通管理部门责令改正，拒不改正的，处以一百元罚款。"""),
        LawArticle("第四十九条", "", """违反本条例第八条规定，驾驶未经公安机关交通管理部门依法登记的非机动车上道路行驶的，由公安机关交通管理部门处以警告或者五十元罚款，并可以扣留车辆至处罚执行完毕和违法行为人提供相应合法证明为止。"""),
        LawArticle("第五十条", "", """违反本条例第九条第一款规定，生产、销售非标准车的，由质量技术监督或者工商等部门依法予以处罚。违反本条例第九条第二款规定，驾驶非标准车上道路行驶，有下列情形之一的，由公安机关交通管理部门处以二百元罚款并可以扣留车辆：（一）未取得临时通行标志或者临时通行标志超过有效期限的；（二）未随车携带临时通行证的；（三）未按规定车道行驶的；（四）违反规定载人载物的。"""),
        LawArticle("第五十一条", "", """违反本条例第十一条第一款规定，从事运输建筑垃圾和预拌混凝土等的车辆，不按照规定喷涂、悬挂放大号牌的，由公安机关交通管理部门责令改正，并处以二百元罚款。"""),
        LawArticle("第五十二条", "", """违反本条例第十二条规定，上道路行驶的机动车和非标准车悬挂的号牌、临时通行标志或者安装、使用的装置，有下列情形之一的，对驾驶人处以二百元罚款；公安机关交通管理部门应当强制拆除、收缴非法装置，并可以扣留车辆至违法状态消除：（一）未悬挂在规定的位置或者故意遮挡、污损的；（二）未保持端正、清晰、完整或者有涂描、倒置、折叠、重叠以及有其他妨碍号牌识别行为的；（三）安装、使用可变式号牌或者其他影响交通技术监控设备识别装置的；（四）安装、使用影响交通技术监控设备正常使用装置的。上道路行驶的非机动车有前款所列情形之一的，由公安机关交通管理部门责令驾驶人立即改正，并处以三十元罚款。属于车辆所有人或者管理人责任的，对车辆所有人或者管理人予以处罚。"""),
        LawArticle("第五十三条", "", """违反本条例第十四条第一款第一项、第二项规定，擅自改变机动车已登记的结构、构造的，处以五百元以下罚款；擅自改变非机动车已登记的结构、构造，改动、拆除电动自行车限速装置，或者对人力三轮车、自行车加装动力装置的，处以五十元罚款。有上述行为的，由公安机关交通管理部门责令立即改正，并可以扣留车辆至违法状态消除。违反本条例第十四条第一款第三项、第四项规定，伪造、变造或者使用伪造、变造以及使用其他非机动车、非标准车的号牌、非机动车登记证、临时通行标志或者临时通行证的，由公安机关交通管理部门予以收缴，并对非机动车的违法行为处以五十元罚款，对非标准车的违法行为处以二百元罚款。违反本条例第十四条第一款第五项、第六项规定，驾驶设置有电子广告装置或者其他影响安全驾驶标识的机动车在道路上行驶、加装射灯的，由公安机关交通管理部门责令改正，并处以二百元罚款。"""),
        LawArticle("第五十四条", "", """违反本条例第二十条第一款规定，在道路两侧及隔离带上设置的管线、照明、广告牌等设施或者种植的植物，出现损坏或者照明不足，遮挡路灯、交通信号灯、交通标志等妨碍安全视距、影响道路交通安全情形的，由公安机关交通管理部门责令行为人或者相关责任单位排除妨碍或者及时修复。拒不执行的，处以五百元以上一千元以下罚款；情节严重的，处以一千元以上二千元以下罚款，并强制排除妨碍或者及时修复，所需费用由行为人或者相关责任单位负担。违反本条例第二十条第二款规定，在道路交通安全设施上晾晒物品或者未经公安机关交通管理部门同意，在交通隔离护栏上悬挂横幅或者设置标牌的，由公安机关交通管理部门强制排除妨碍并可对行为人处以二百元罚款。违反本条例第二十一条规定，占用道路打谷、晾晒物品、堆物作业或者进行其他妨碍道路交通安全活动的，由公安机关交通管理部门强制排除妨碍。"""),
        LawArticle("第五十五条", "", """违反本条例第二十二条、第二十三条规定，影响道路交通安全，有下列情形之一的，由公安机关交通管理部门责令行为人停止违法行为；有第一项、第五项行为的，可以并处二百元以上一千元以下罚款：（一）未征得公安机关交通管理部门的同意，占用、挖掘道路的;（二）施工单位未在施工路段两端设置明显的安全警示标志和安全防护措施或者未在绕行处设置标志的；（三）道路作业单位在道路上进行维修、养护、清扫、绿化等作业时，未采取必要的交通安全防护措施，未使用喷涂或者粘贴有醒目反光材料车辆的；（四）施工完毕后，未经道路主管部门和公安机关交通管理部门验收合格，即恢复通行的；（五）道路作业单位在高架道路、立交桥、下穿道路等特殊路段进行作业，未征得公安机关交通管理部门同意的。"""),
        LawArticle("第五十六条", "", """违反本条例第二十九条规定，设置转弯待行区的交叉路口，同方向直行车辆放行时，转弯车辆未依次进入待行区等候的，由公安机关交通管理部门责令改正，可以处以一百元罚款。"""),
        LawArticle("第五十七条", "", """违反本条例第三十条第十项规定，叉车、轮式专用机械车未按照公安机关交通管理部门指定的时间和路线上道路行驶的，由公安机关交通管理部门责令改正，并处以一百元罚款。"""),
        LawArticle("第五十八条", "", """违反本条例第三十三条规定，取得黄色环保检验合格标志以及未取得环保检验合格标志的机动车，进入禁止通行区域行驶的，由公安机关交通管理部门责令驾驶人驶出禁止通行区域，并处以一百元罚款。"""),
        LawArticle("第五十九条", "", """违反本条例第三十五条、第三十六条，驾驶公共汽车、出租车以及其他各类营运车辆违反规定行驶或者停车的，由公安机关交通管理部门处以一百元罚款。"""),
        LawArticle("第六十条", "", """违反本条例第三十七条、第三十八条规定，非机动车、行人进入下穿道路通行的，由公安机关交通管理部门责令改正，并处以警告或者五十元罚款。违反本条例第三十八条第一项、第二项规定，行人或者乘车人移动、钻爬、跨越、倚坐道路隔离设施或者在车行道上停留、乞讨、兜售物品、散发宣传品以及有其他妨碍道路交通安全的行为，由公安机关交通管理部门责令改正，并处以警告或者五十元罚款。"""),
        LawArticle("第六十一条", "", """驾驶摩托车、非标准车、残疾人机动轮椅车、人力三轮车以及加装动力装置的非机动车在市区禁止通行的道路上行驶或者违反规定带人的，公安机关交通管理部门可以扣留车辆，并对驾驶人依法予以处罚。"""),
        LawArticle("第六十二条", "", """低速载货汽车、三轮汽车、拖拉机、变型拖拉机违反道路交通安全管理规定以及非机动车驾驶人拒绝接受罚款处罚的，公安机关交通管理部门可以扣留车辆。"""),
        LawArticle("第六十三条", "", """公安机关交通管理部门依法扣留的车辆，驾驶人或者所有人、管理人在规定的期限内未接受处理以及因当事人原因无法依法返还的，公安机关交通管理部门可以将车辆依法拍卖、拆除、报废解体。"""),
        LawArticle("第六十四条", "", """对通过照相、摄像、测速仪、酒精测试仪、称重仪、交通违法自动记录系统以及其他交通技术监控检测设备获取的资料认定的交通安全违法行为，公安机关交通管理部门可以对违法的机动车驾驶人或者所有人、管理人依法予以处罚。"""),
        LawArticle("第六十五条", "", """公安机关交通管理部门及其交通警察不严格执法或者有违法违纪行为的，依据《中华人民共和国道路交通安全法》第一百一十五条的规定，对直接负责的主管人员和其他直接责任人员给予相应的行政处分。"""),
        LawArticle("第六十六条", "", """公安机关交通管理部门、安全生产、交通、规划、环保、城市管理、园林、教育、农业（农业机械）、卫生、质量技术监督、工商等部门以及开发区管理机构及其工作人员，不履行相关职责，造成重特大交通事故或者其他严重后果的，对直接负责的主管人员和直接责任人员依法给予相应的行政处分。"""),
        LawArticle("第六十七条", "", """本条例所称非标准车，是指设计最高时速、空车质量、外形尺寸以及其他车辆要素既不符合非机动车产品国家标准，又不符合机动车产品国家标准的由动力装置驱动、牵引的轮式车辆或者机具（含所有两轮、三轮、四轮及多轮车型或者机具）。本条例所称高架道路是指与地面保持一定空间的道路和列入高架道路交通管理的地面连接道路。本条例中市区道路的范围，由市人民政府根据本市经济社会发展的状况确定并公告。"""),
        LawArticle("第六十八条", "", """本条例自2014年1月1日起施行。2004年8月20日安徽省第十届人民代表大会常务委员会第十一次会议批准的《合肥市城市道路交通安全管理条例》同时废止。热点新闻更多>>人大要闻全国人大环资委来皖调研汪卫东主持召开市人大常委会党组理论学习中心组学习会议市十七届人大常委会举行第二十九次会议汪卫东出席并讲话市十七届人大常委会举行第八十七次主任会议汪卫东主持市人大常委会党组召开扩大会议汪卫东主持并讲话市十七届人大常委会举行第八十六次主任会议汪卫东主持市人大常委会党组召开扩大会议汪卫东主持会议并讲话更多>>工作动态市委第二巡察组巡察公告市人大常委会机关开展“夏日送清凉”慰问活动市人大常委会机关举办2025年第二期“年轻干部讲坛”市人大常委会机关赴肥东县八斗镇南桥社区开展入村走访并作党课报告市人大常委会机关赴肥西县调研全过程人民民主实践站工作开展情况市人大常委会机关召开新任职干部、关键岗位干部及年轻干部深入贯彻中央八项规定精神学习教育学习交流会市人大常委会党组深入贯彻中央八项规定精神学习教育集中交流研讨暨理论学习中心组学习会议召开更多>>县乡人大蜀山区人大常委会聚焦基层行政执法开展专题调研肥西县人大召开民生实事项目人大代表票决制暨“进站会商一件事”工作推进会长丰县人大常委会组织开展“人大代表看长丰”暨代表议案办理观摩活动庐阳区人大常委会开展安全生产“一法一条例”执法检查庐阳区人大常委会召开建设全过程人民民主实践站、丰富拓展基层民主形式工作现场会庐江县人大常委会召开2025年城市管理工作专题询问会瑶海区人大践行全过程人民民主中心实践站开展首场活动主办单位：合肥市人大常委会版权所有皖ICP备19024198号-2"""),
    )
)

val LF2_HEFEI_NON_MOTOR: LawBook = LawBook(
    id = "hefei_non_motor",
    name = "合肥市非机动车安全管理条例",
    articlesCount = 34,
    chapters = 7,
    intro = """2022年9月通过，2022年11月1日施行。合肥市非机动车（含电动自行车）生产、销售、登记、通行、停放充电全链条管理，全文收录（共34条）。来源：合肥市人大常委会。""",
    articles = listOf(
        LawArticle("第一条", "", """为了加强非机动车管理，预防和减少交通、火灾等安全事故，保障人身、财产安全，根据《中华人民共和国道路交通安全法》和有关法律、行政法规，结合本市实际，制定本条例。"""),
        LawArticle("第二条", "", """本条例适用于本市行政区域内非机动车的生产、销售、登记、通行、停放、充电及其安全管理活动。本条例所称非机动车，是指以人力或者畜力驱动，上道路行驶的交通工具，以及虽然有动力装置驱动但是设计最高时速、空车质量、外形尺寸符合有关国家标准的残疾人机动轮椅车、电动自行车等交通工具。"""),
        LawArticle("第三条", "", """市、县（市）区人民政府应当加强统一领导，建立非机动车安全管理责任制，完善非机动车通行、停放、充电等基础设施规划建设，优化非机动车公共交通网络布局。市、县（市）区人民政府应当建立联席会议制度，协调解决非机动车安全管理有关重大问题。乡镇人民政府、街道办事处应当组织落实辖区内非机动车安全宣传教育和规范停放、安全充电换电等管理工作，推动社区参与非机动车综合治理。"""),
        LawArticle("第四条", "", """公安机关负责组织实施本条例，并依法做好非机动车登记和道路通行管理等工作。市场监督管理部门负责非机动车生产、销售以及相关产品质量的监督管理。城市管理部门会同公安机关负责公共场所非机动车停放的监督管理。交通运输部门负责互联网租赁非机动车投放运营的监督管理。消防救援机构负责非机动车违反消防安全管理规定停放、充电行为的监督管理。发展和改革、财政、自然资源和规划、生态环境、城乡建设、商务、住房保障和房产管理、林业和园林、邮政管理、残联等部门和单位在各自职责范围内，依法做好非机动车安全管理相关工作。"""),
        LawArticle("第五条", "", """相关行业组织应当加强行业自律，组织制定非机动车安全管理行业规范，引导、协调、监督会员单位依法从事非机动车生产、销售、回收等经营活动，协助政府有关部门做好非机动车安全管理工作。"""),
        LawArticle("第六条", "", """在本市生产、销售的非机动车应当符合国家标准。电动自行车的蓄电池、电动机、充电器、安全头盔等相关产品应当符合相关标准。电动自行车、残疾人机动轮椅车销售者应当在销售场所醒目位置公示所售非机动车取得国家强制性产品认证的相关信息；通过电子商务平台进行销售的，应当在披露的商品信息中包含相关信息。"""),
        LawArticle("第七条", "", """电动自行车所有人应当按照有害垃圾依法分类处理电动自行车的废旧电池，不得随意丢弃。鼓励电动自行车生产者、销售者采取以旧换新等方式回收废旧电动自行车及其废旧电池。电动自行车生产者、销售者应当按照国家固体废物管理的相关规定将废旧电池集中处置。"""),
        LawArticle("第八条", "", """单位和个人不得违反规定从事下列行为：（一）拼装非机动车；（二）加装、改装、更换不符合相关标准的蓄电池、电动机；（三）加装、改装座位或者加装遮阳篷、挡风板等影响安全驾驶的装置；（四）拆除或者改动限速装置；（五）从事拼装、加装、改装电动自行车经营性活动；（六）法律、法规规定不得从事的其他行为。"""),
        LawArticle("第九条", "", """电动自行车、残疾人机动轮椅车应当依法登记，取得非机动车号牌后，方可上道路行驶。禁止伪造、变造或者使用伪造、变造的非机动车号牌。禁止使用其他非机动车的号牌。"""),
        LawArticle("第十条", "", """个人所有的非机动车免费登记发放号牌。公安机关交通管理部门应当对互联网租赁电动自行车核发专用号牌。"""),
        LawArticle("第十一条", "", """不符合相关标准的电动自行车，已按照有关规定在本市取得临时通行标识的，以及在外地取得临时通行标识且在有效期内的，超过本市规定临时通行期限的，不得上道路行驶。"""),
        LawArticle("第十二条", "", """新建城市道路，应当按照国家有关标准同步规划、建设非机动车道，并设置标识标线。已建成城市道路，未设置非机动车道的，有关部门应当根据需要调整或者改建非机动车道，并配套完善交通设施。公安机关交通管理部门应当根据交通流量、安全状况，组织有关部门对具备条件的道路路口设置右转危险区域，并配套完善交通设施。"""),
        LawArticle("第十三条", "", """驾驶电动自行车、残疾人机动轮椅车上道路行驶，应当按照规定安装号牌，并保持号牌完整、清晰，不得污损、遮挡、倒置。驾驶非机动车上道路行驶，应当遵守下列规定：（一）遵守交通信号，服从交通管理人员的指挥；（二）在非机动车道内行驶，没有非机动车道的，靠车行道的右侧行驶；（三）遇红灯时，在非机动车停止线内有序等候；（四）电动自行车驾驶人和乘坐人佩戴安全头盔；（五）遇行人正在通过人行横道时，停车让行；（六）载物时采取加固措施，防止物品散落；（七）电动自行车、残疾人机动轮椅车在夜间或者遇有雨、雪、雾、沙尘、冰雹等低能见度情况下行驶时，开启照明装置；（八）法律、法规的其他通行规定。"""),
        LawArticle("第十四条", "", """禁止驾驶拼装、加装、改装的电动自行车上道路行驶。驾驶非机动车上道路行驶，不得有下列行为：（一）逆向行驶；（二）醉酒驾驶；（三）驶入高速公路、高架道路、隧道或者未设置非机动车道的城市快速路、桥梁、下穿道路；（四）牵引动物、以手持方式拨打或者接听电话、浏览电子设备等影响安全驾驶的行为；（五）违反规定载运爆炸物品、易燃易爆化学物品以及剧毒、放射性等危险物品；（六）法律、法规规定的其他禁止行为。"""),
        LawArticle("第十五条", "", """县（市）区人民政府应当组织有关部门划定本辖区的非机动车停放场地，设置明显标识。有条件的场地，可以配置电动自行车充电换电设施，有关部门应当支持开展充电换电服务。非机动车应当按照指定地点有序停放。未设置停放地点的，非机动车停放不得影响道路通行、占用或者影响公共设施的使用。"""),
        LawArticle("第十六条", "", """国家机关、企业事业单位、社会团体、个体工商户等，应当维护其市容和环境卫生责任区范围内的非机动车停车秩序；对随意停放非机动车的，有权予以劝阻，引导其停放至非机动车停放场地，劝阻无效的，可以向公安机关、城市管理部门举报，公安机关、城市管理部门应当及时处理。"""),
        LawArticle("第十七条", "", """下列区域不得停放非机动车：（一）消防车通道、消防车登高操作场地、疏散通道、安全出口、公交及轨道交通站点等公共设施处；（二）公共场所出入口；（三）机动车道、非机动车道；（四）未划定停放区域的人行道；（五）法律、法规规定其他禁止停放的区域。"""),
        LawArticle("第十八条", "", """客运车站、轨道交通站点等交通集散地以及医院、学校、商场、写字楼、集贸市场、步行街、影剧院、体育场馆、展览馆、旅游景点等人员流动较多的公共场所，应当在规划建设阶段同步配套规划建设非机动车停放场所。未同步配套规划建设的，其所有人或者管理人应当设置非机动车停放场地。国家机关、企业事业单位以及住宅小区、商业楼宇的管理单位应当为网络餐饮外卖和快递服务配送车辆提供便利。"""),
        LawArticle("第十九条", "", """新建、改建、扩建住宅小区，应当按照有关规定配套建设非机动车集中停放场所以及充电设施。市、县（市）区人民政府应当采取措施，推动已建成的住宅小区配套建设非机动车集中停放场所以及充电设施。"""),
        LawArticle("第二十条", "", """电动自行车充电时应当确保安全，不得违反用电安全要求私拉电线和插座充电。物业服务企业应当加强物业管理区域内电动自行车停放、充电的管理，开展日常巡查和安全用电宣传，对违反用电安全要求私拉电线和插座充电的，应当及时劝阻；不听劝阻的，应当及时向公安、消防救援机构、城市管理等有关部门报告。未实行物业管理或者业主自行管理的住宅小区，由乡镇人民政府、街道办事处负责电动自行车停放、充电安全的日常监督管理工作。"""),
        LawArticle("第二十一条", "", """电动自行车不得在下列场所充电：（一）高层民用建筑物公共门厅、楼梯间、疏散通道、安全出口等共用部位；（二）人员密集场所的室内区域；（三）法律、法规规定其他禁止充电的场所。"""),
        LawArticle("第二十二条", "", """本市互联网租赁非机动车实行总量控制。总量规模由交通运输部门会同公安机关、城市管理部门，根据城市公共资源承载能力、交通出行需求等因素合理确定，并实行动态调整。"""),
        LawArticle("第二十三条", "", """交通运输部门应当建立总量控制、动态管理和淘汰机制以及行业信息服务平台，实施服务质量评价制度，督促互联网租赁非机动车运营企业落实管理主体责任。"""),
        LawArticle("第二十四条", "", """互联网租赁非机动车运营企业应当遵循总量调控和动态管理机制要求，有序投放和回收车辆。新增车辆的，互联网租赁非机动车运营企业应当在投放运营前三十日，向交通运输部门报送车辆投放方案。回收车辆的，互联网租赁非机动车运营企业应当自收到交通运输部门通知之日起三十日内，完成相关车辆回收工作。"""),
        LawArticle("第二十五条", "", """市城市管理部门应当制定互联网租赁非机动车停放点位设置技术要求。城市管理部门应当会同公安机关交通管理部门加强停放秩序监督管理，发现未在停放点停放的，应当通知互联网租赁非机动车运营企业及时清理。"""),
        LawArticle("第二十六条", "", """互联网租赁非机动车运营企业应当做好下列工作：（一）加强日常停放、调度管理，运用现代信息技术手段规范停放，及时平衡区域潮汐时段车辆供给；（二）建立日常巡查制度，每日清理未在停放点停放车辆和损坏、废弃车辆；（三）为电动自行车配备安全头盔，并提示驾驶人佩戴；（四）法律、法规规定的其他工作。"""),
        LawArticle("第二十七条", "", """违反本条例规定的行为，法律、法规已有处罚规定的，从其规定。"""),
        LawArticle("第二十八条", "", """违反本条例第八条第五项规定，违反规定从事拼装、加装、改装电动自行车经营性活动的，由市场监督管理部门责令改正，处以二千元以上二万元以下的罚款。"""),
        LawArticle("第二十九条", "", """违反本条例规定，有下列情形之一的，按照《安徽省电动自行车管理条例》有关规定予以处罚：（一）电动自行车驾驶人或者乘坐人未佩戴安全头盔的；（二）电动自行车、残疾人机动轮椅车在夜间或者遇有雨、雪、雾、沙尘、冰雹等低能见度情况下行驶时未开启照明装置的；（三）牵引动物、以手持方式拨打或者接听电话、浏览电子设备的。"""),
        LawArticle("第三十条", "", """违反本条例第十四条第一款规定，驾驶拼装、加装、改装的电动自行车上道路行驶的，由公安机关交通管理部门责令改正，并按照《安徽省电动自行车管理条例》有关规定予以处罚。"""),
        LawArticle("第三十一条", "", """违反本条例第十七条第三项、第四项规定，在机动车道、非机动车道、未划定停放区域的人行道停放非机动车妨碍其他车辆和行人通行的，由公安机关交通管理部门责令改正；驾驶人在现场拒不改正的，对其处以警告或者五元以上五十元以下的罚款，驾驶人拒绝接受罚款处罚的，可以扣留其非机动车；驾驶人不在现场的，可以搬移至不妨碍交通的地点。"""),
        LawArticle("第三十二条", "", """违反本条例第二十一条第一项规定，电动自行车在高层民用建筑物公共门厅、楼梯间、疏散通道、安全出口等共用部位充电的，由消防救援机构责令改正。拒不改正的，对经营性单位和个人处以二千元以上一万元以下的罚款，对非经营性单位和个人处以五百元以上一千元以下的罚款。"""),
        LawArticle("第三十三条", "", """违反本条例第二十六条第二项规定，互联网租赁非机动车运营企业对未在停放点停放的车辆未每日进行清理、影响行人和车辆正常通行的，由城市管理部门责令改正。拒不改正的，处以一千元以上五千元以下的罚款。"""),
        LawArticle("第三十四条", "", """本条例自2022年11月1日起施行。热点新闻更多>>人大要闻全国人大环资委来皖调研汪卫东主持召开市人大常委会党组理论学习中心组学习会议市十七届人大常委会举行第二十九次会议汪卫东出席并讲话市十七届人大常委会举行第八十七次主任会议汪卫东主持市人大常委会党组召开扩大会议汪卫东主持并讲话市十七届人大常委会举行第八十六次主任会议汪卫东主持市人大常委会党组召开扩大会议汪卫东主持会议并讲话更多>>工作动态市委第二巡察组巡察公告市人大常委会机关开展“夏日送清凉”慰问活动市人大常委会机关举办2025年第二期“年轻干部讲坛”市人大常委会机关赴肥东县八斗镇南桥社区开展入村走访并作党课报告市人大常委会机关赴肥西县调研全过程人民民主实践站工作开展情况市人大常委会机关召开新任职干部、关键岗位干部及年轻干部深入贯彻中央八项规定精神学习教育学习交流会市人大常委会党组深入贯彻中央八项规定精神学习教育集中交流研讨暨理论学习中心组学习会议召开更多>>县乡人大蜀山区人大常委会聚焦基层行政执法开展专题调研肥西县人大召开民生实事项目人大代表票决制暨“进站会商一件事”工作推进会长丰县人大常委会组织开展“人大代表看长丰”暨代表议案办理观摩活动庐阳区人大常委会开展安全生产“一法一条例”执法检查庐阳区人大常委会召开建设全过程人民民主实践站、丰富拓展基层民主形式工作现场会庐江县人大常委会召开2025年城市管理工作专题询问会瑶海区人大践行全过程人民民主中心实践站开展首场活动主办单位：合肥市人大常委会版权所有皖ICP备19024198号-2"""),
    )
)

val LF2_ANHUI_EBIKE: LawBook = LawBook(
    id = "anhui_ebike",
    name = "安徽省电动自行车管理条例",
    articlesCount = 49,
    chapters = 7,
    intro = """2022年12月通过，2023年3月1日施行。安徽省电动自行车管理地方性法规，全文收录（共49条）。来源：安徽省人民政府公开发布。""",
    articles = listOf(
        LawArticle("第一条", "", """为了加强电动自行车管理，维护道路交通秩序，引导文明出行，预防和减少事故，保护人身、财产安全，根据《中华人民共和国道路交通安全法》和有关法律、行政法规，结合本省实际，制定本条例。"""),
        LawArticle("第二条", "", """本条例适用于本省行政区域内的电动自行车生产、销售、维修、登记、通行、停放以及相关保障与管理活动。本条例所称电动自行车，是指以车载蓄电池作为辅助能源，具有脚踏骑行能力，能实现电助动、电驱动功能的两轮自行车。"""),
        LawArticle("第三条", "", """电动自行车管理应当遵循依法规范、保障安全、方便群众、源头管理、协同共治的原则。"""),
        LawArticle("第四条", "", """各级人民政府应当加强对本行政区域内电动自行车管理工作的领导，建立协调机制，统筹保障管理工作所需经费，督促有关部门依法履行监督管理职责，组织落实电动自行车安全通行、规范停放、安全充电等保障措施，引导公民安全出行、文明出行、绿色出行。"""),
        LawArticle("第五条", "", """县级以上人民政府经济和信息化部门负责电动自行车生产企业的行业管理工作。县级以上人民政府市场监督管理部门负责电动自行车、蓄电池、充电桩等有关产品质量以及相关生产、销售行为的监督管理工作。县级以上人民政府公安机关交通管理部门负责电动自行车登记和道路交通安全管理工作。县级以上人民政府住房城乡建设、城市管理、生态环境、交通运输、邮政管理、财政等部门和消防救援机构按照各自职责，负责电动自行车管理有关工作。"""),
        LawArticle("第六条", "", """国家机关、企业事业单位、社会团体以及其他组织应当对本单位的人员开展电动自行车安全教育。教育行政部门、学校应当将电动自行车安全教育纳入法治宣传教育内容。村（居）民委员会、物业服务企业应当开展电动自行车安全宣传。广播、电视、报刊、网络等媒体应当加强对电动自行车管理法律、法规和安全知识的公益宣传。"""),
        LawArticle("第七条", "", """电动自行车相关行业协会、商会应当建立健全行业规范，加强行业自律，反映行业诉求，引导、督促成员单位依法从事电动自行车及相关产品生产、销售、维修、租赁、回收等经营活动。"""),
        LawArticle("第八条", "", """在本省生产、销售的电动自行车，设计最高时速、整车质量、外形尺寸、制动性能、防火阻燃性能等应当符合强制性国家标准。生产、销售和维修更换的电动自行车充电器、蓄电池、电动机等零部件，生产、销售的安全头盔，应当符合相关国家标准的安全要求。"""),
        LawArticle("第九条", "", """电动自行车生产者或者销售者、进口商应当委托国家认证认可监督管理部门指定的认证机构，对其生产、销售或者进口的电动自行车进行强制性产品认证。"""),
        LawArticle("第十条", "", """电动自行车销售者应当销售符合强制性国家标准且经过强制性产品认证的电动自行车，并向消费者提供购车发票、产品合格证或者进口凭证。电动自行车销售者应当建立并执行进货检查验收制度，在销售场所醒目位置、电子商务平台产品主页公示所售电动自行车产品认证的相关信息，并开展电动自行车安全使用等宣传。省人民政府市场监督管理部门应当向社会公开电动自行车获得强制性产品认证相关信息的查询途径。"""),
        LawArticle("第十一条", "", """任何单位和个人不得实施下列影响电动自行车质量和道路交通安全的行为：（一）拼装电动自行车；（二）加装、改装或者更换电动机、蓄电池等动力装置，导致电动自行车不符合强制性国家标准；（三）拆除或者改换限速装置，导致最高时速超过强制性国家标准；（四）改变电动自行车铭牌、电动机编码、整车编码等；（五）违反规定加装车篷、雨棚、车厢等装置，影响交通安全。禁止具有前款所列情形之一的电动自行车上道路行驶。"""),
        LawArticle("第十二条", "", """鼓励电动自行车生产者、销售者采取以旧换新、折价回购等方式回收废旧电动自行车和不符合强制性国家标准的电动自行车。电动自行车所有人将废旧蓄电池送交电动自行车生产者、销售者处理的，生产者、销售者应当提供更换、回收服务。属于危险废物的废旧蓄电池，应当交由具有资质的单位收集、贮存、利用、处置。"""),
        LawArticle("第十三条", "", """电动自行车应当经市、县人民政府公安机关交通管理部门登记，取得电动自行车号牌，方可上道路行驶。"""),
        LawArticle("第十四条", "", """申请电动自行车登记的，应当自购车之日起十五日内向公安机关交通管理部门申请登记，填写申请表，交验车辆，提交身份证明、购车发票等来历证明、车辆产品合格证或者进口凭证。尚未登记的，驾驶人持购车发票或者其他合法来源凭证，可以自购车之日起十五日内临时上道路行驶。本条例施行前已经购买使用的电动自行车，由市、县公安机关交通管理部门组织办理登记工作。"""),
        LawArticle("第十五条", "", """对申请登记的电动自行车，公安机关交通管理部门应当审查提交的登记材料、查验车辆。对符合强制性国家标准，且申请材料齐全有效的，应当当场登记并免费发放电动自行车号牌；对不符合强制性国家标准的，不予登记并说明理由；对申请材料不齐全的，应当一次性书面告知申请人补正相关材料。办理登记时，应当通过发放安全驾驶宣传资料、播放宣传视频等方式，对驾驶人进行道路交通、消防安全法律、法规和安全知识教育。"""),
        LawArticle("第十六条", "", """电动自行车所有人姓名或者所属单位名称、联系方式、电动机等登记内容发生变更的，应当向公安机关交通管理部门申请变更登记。已登记的电动自行车所有权发生转移的，受让人应当自车辆交付之日起三十日内向公安机关交通管理部门申请办理转移登记并提交原所有人和现所有人的身份证明。已登记的电动自行车遗失、灭失或者不再使用的，所有人应当向公安机关交通管理部门申请办理注销登记。电动自行车号牌损坏、遗失的，所有人应当向公安机关交通管理部门申请补办。"""),
        LawArticle("第十七条", "", """公安机关交通管理部门应当采取设立办理点、简化办理程序、建设电动自行车登记信息系统、推行网上办理等措施，为办理电动自行车登记、信息查询等提供便利。"""),
        LawArticle("第十八条", "", """在《电动自行车安全技术规范》（GB17761-2018）实施前购买的不符合强制性国家标准的电动自行车，发放临时通行标识。临时通行期限自本条例施行之日起最长不超过三年，设区的市可以就具体期限作出规定。取得临时通行标识的电动自行车，在临时通行期限内上道路行驶的，应当遵守本条例的规定。临时通行期满后，不得上道路行驶。在省外取得临时通行标识但已超过其有效期的电动自行车，不得上道路行驶。"""),
        LawArticle("第十九条", "", """电动自行车号牌、临时通行标识的式样，由省人民政府公安机关交通管理部门监制，市、县人民政府公安机关交通管理部门负责制作发放。本条例施行前已经制作发放的电动自行车号牌、临时通行标识继续有效。"""),
        LawArticle("第二十条", "", """驾驶电动自行车上道路行驶，应当保持电动自行车的制动、鸣号、灯光和夜间反光装置等符合安全技术要求。"""),
        LawArticle("第二十一条", "", """驾驶电动自行车上道路行驶，应当在指定位置悬挂号牌或者临时通行标识，并保持清晰、完整，不得故意遮挡、污损。任何单位和个人不得伪造、变造、买卖号牌或者临时通行标识，不得使用伪造、变造的号牌或者临时通行标识，不得使用其他电动自行车的号牌或者临时通行标识。"""),
        LawArticle("第二十二条", "", """驾驶电动自行车上道路行驶，应当遵守下列通行规定：（一）有非机动车道的，在非机动车道内行驶，不得在人行道内行驶；没有非机动车道的，在车行道的右侧行驶；（二）按照交通信号的指示通行；遇有交通警察现场指挥时，应当按照交通警察的指挥通行；在没有交通信号的道路上，应当在确保安全、畅通的原则下通行；（三）遇红灯时，在路口停止线以外或者待驶（转）区内依次等候；（四）转弯前减速慢行，注意观察，提前示意；（五）行经人行横道时，减速行驶；遇行人正在通过人行横道的，停车礼让；行经没有交通信号的道路时，遇行人横过道路，应当避让；（六）在夜间或者遇有雨、雾、雪、沙尘等低能见度情况行驶时，应当开启照明灯光；（七）法律、法规规定的其他通行规定。驾驶人和搭载人应当规范佩戴安全头盔。"""),
        LawArticle("第二十三条", "", """驾驶电动自行车上道路行驶，不得有下列妨碍安全驾驶的行为：（一）醉酒驾驶、服用国家管制的精神药品或者麻醉药品后驾驶；（二）逆向行驶、追逐竞驶；（三）牵引动物、浏览电子设备、以手持方式拨打接听电话等；（四）驶入高速公路、城市快速路等禁止非机动车通行的区域；（五）在非机动车道内行驶时最高时速超过十五公里；（六）法律、法规规定的其他妨碍安全驾驶的行为。"""),
        LawArticle("第二十四条", "", """在道路上驾驶电动自行车应当年满十六周岁，且无妨碍安全驾驶的身体缺陷、疾病。成年人驾驶电动自行车仅限搭载一人，但是驾驶不具备搭载条件的电动自行车不得载人。搭载人应当在驾驶人后方正向骑坐。搭载六周岁以下未成年人的应当采取使用安全座椅等保护措施。十六周岁以上未成年人驾驶电动自行车不得搭载人员。驾驶电动自行车载物，高度从地面起不得超过1.5米，宽度左右各不得超出车把0.15米，长度前端不得超出车轮，后端不得超出车身0.3米。"""),
        LawArticle("第二十五条", "", """电动自行车在公共场所停放，应当停放在非机动车停放区域内；没有设置非机动车停放区域的，车辆停放不得占用盲道、人行道、消防通道，不得妨碍其他车辆和行人通行，不得影响市容环境。在道路周边停放电动自行车，应当使用非机动车道路停放点。未停放在非机动车道路停放点，影响其他车辆和行人通行且驾驶人不在现场的，公安机关交通管理部门可以会同城市管理等有关部门对现场予以整理，规范停放。沿街单位应当规范、有序停放电动自行车，不得随意停放。沿街单位对在其市容环境卫生责任区内随意停放电动自行车的，有权予以劝阻或者向公安机关交通管理、城市管理等有关部门举报。县级以上人民政府城市管理部门应当在公共场所合理划定非机动车停放区域，引导电动自行车有序停放，加强电动自行车停放管理。"""),
        LawArticle("第二十六条", "", """禁止电动自行车在建筑物公共门厅、楼梯间、疏散通道、安全出口、消防车通道及其两侧影响通行的区域、人员密集场所的室内区域停放、充电。禁止违反用电安全要求，在住宅内充电或者私拉电线和插座充电。禁止电动自行车进入载人电梯。对违反前款规定的行为，村（居）民委员会、主管单位、物业服务企业、业主委员会和业主有权予以劝阻；对不听劝阻的，可以向消防救援机构、公安派出所等举报。负有消防监督管理职责的部门应当公布投诉举报方式，依法受理、处理投诉举报，对有关单位履行电动自行车消防安全管理职责的情况进行监督检查。"""),
        LawArticle("第二十七条", "", """新建、改建、扩建城市道路应当按照城市道路建设标准和规范，规划和建设非机动车道；已经建成的城市道路没有建设非机动车道的，应当采取措施逐步建设。有关主管部门应当加强对非机动车道的养护和管理，保证车道平整通畅。大型车辆通行频繁的城市道路，应当在机动车右转弯位置施划右转弯导向线和危险警示区。"""),
        LawArticle("第二十八条", "", """地铁站、车站、码头、医院、校园、商场、农贸市场、展览馆、影剧院、体育场馆、公园等公共建筑、公共场所建设单位应当按照有关规定和标准，配套规划、建设非机动车公共停放场所和设施。住宅小区和其他建筑的建设单位应当按照规划和有关标准建设非机动车停放场所和设施。已建住宅小区和其他建筑的建设单位未建设非机动车集中停放场所的，应当划设相对集中的非机动车停放区域。非机动车停放场所和设施管理、使用单位应当按照规划用途使用非机动车停放场所和设施，不得擅自停用或者改变用途。非机动车停放场所和设施管理、使用单位可以根据需要，依法划设临时停放区域，为快递、外卖等配送车辆提供便利。"""),
        LawArticle("第二十九条", "", """新建、改建、扩建住宅小区和其他建筑，建设单位应当按照规划和有关标准建设和管理电动自行车充电设施；已建成的住宅小区和其他建筑应当采取措施逐步建设电动自行车充电设施。电动自行车应当使用充电设施充电。电动自行车集中停放场所和充电设施应当符合消防安全技术标准。有关方面应当对已经建成的电动自行车集中停放场所和设施进行检查评估，不符合消防安全技术标准的应当及时整改。建设管理单位或者物业服务企业应当加强日常管理，做好巡查检查，定期检修电动自行车充电线路，防止线路老化、短路。从事电动自行车充换电设施运营的单位建设充换电设施的，应当符合相关技术规范和标准，落实安全监督和日常管理责任。"""),
        LawArticle("第三十条", "", """使用电动自行车从事快递、外卖等经营活动的企业应当落实安全生产主体责任，加强交通安全知识培训，为电动自行车驾驶人配备安全头盔，规范设置外卖、快递的装载、运输装置；依法办理工伤保险，可以通过购买第三者责任险、驾驶人员人身意外伤害险等方式提高偿付能力。"""),
        LawArticle("第三十一条", "", """从事互联网电动自行车租赁业务的企业，应当落实主体责任，按照当地人民政府确定的投放区域、数量并采用技术手段进行定点投放；随车提供安全头盔，定期消毒、维护、增补，保障其安全使用；根据需要为所属电动自行车购买第三者责任险、驾驶人员人身意外伤害险等相应的保险；配备必要的管理人员，做好电动自行车的规范投放和有序停放工作。从事互联网电动自行车租赁业务的企业应当对车辆进行日常检测和维护。互联网租赁电动自行车挤占人行道、车行道、绿化道等道路、区域停放的，运营企业应当及时清理。"""),
        LawArticle("第三十二条", "", """鼓励电动自行车所有人投保第三者责任保险、驾乘人员人身意外伤害保险等险种。"""),
        LawArticle("第三十三条", "", """申请补办电动自行车号牌或者临时通行标识，应当按照规定缴纳工本费。"""),
        LawArticle("第三十四条", "", """公安机关交通管理部门对电动自行车驾驶人违反道路交通安全法律、法规的行为实施行政处罚时，应当坚持处罚与教育相结合。对情节轻微，未影响道路通行的，指出违法行为，给予口头警告后放行。"""),
        LawArticle("第三十五条", "", """违反本条例第八条规定，生产、销售不符合保障人体健康和人身、财产安全的国家标准、行业标准的电动自行车及蓄电池等相关产品的，由市场监督管理部门责令停止生产、销售，没收违法生产、销售的产品，并处违法生产、销售产品（包括已售出和未售出的产品）货值金额等值以上三倍以下罚款；有违法所得的，并处没收违法所得；情节严重的，依法吊销营业执照。"""),
        LawArticle("第三十六条", "", """违反本条例第九条、第十条第一款规定，电动自行车未经强制性产品认证，擅自出厂、销售、进口或者在其他经营活动中使用的，由市场监督管理部门依法处罚。"""),
        LawArticle("第三十七条", "", """违反本条例第十一条第一款规定，从事拼装、加装、改装电动自行车经营性活动的，由市场监督管理部门责令改正，处二千元以上二万元以下罚款；有违法所得的，没收违法所得。违反本条例第十一条第二款规定，驾驶拼装、改装、加装的电动自行车上道路行驶的，由公安机关交通管理部门责令改正，处二百元罚款；公安机关交通管理部门可以依法收缴拼装的电动自行车。"""),
        LawArticle("第三十八条", "", """违反本条例第十三条规定，驾驶未经登记的电动自行车上道路行驶的，由公安机关交通管理部门责令改正，处警告或者五十元罚款。违反本条例第十八条规定，驾驶未取得临时通行标识或者临时通行期满的车辆上道路行驶的，由公安机关交通管理部门责令改正，处二百元罚款。"""),
        LawArticle("第三十九条", "", """违反本条例第二十一条第一款规定，未按照规定在指定位置悬挂号牌或者临时通行标识的，由公安机关交通管理部门责令改正；拒不改正的，处警告或者二十元罚款。违反本条例第二十一条第二款规定，伪造、变造、买卖号牌或者临时通行标识的，由公安机关交通管理部门处二千元以上二万元以下罚款，收缴伪造、变造、买卖的号牌或者临时通行标识；使用伪造、变造的号牌或者临时通行标识，使用其他车辆号牌或者临时通行标识的，由公安机关交通管理部门对驾驶人处二百元以上五百元以下罚款，收缴伪造、变造的号牌或者临时通行标识，可以依法扣留车辆。"""),
        LawArticle("第四十条", "", """违反本条例第二十二条规定的，由公安机关交通管理部门处警告或者五元以上五十元以下罚款。"""),
        LawArticle("第四十一条", "", """违反本条例第二十三条第一项规定，醉酒驾驶，或者违反第二项至第五项规定情形之一的，由公安机关交通管理部门处警告或者五十元罚款。"""),
        LawArticle("第四十二条", "", """违反本条例第二十四条规定，驾驶电动自行车载人影响通行安全的，由公安机关交通管理部门责令改正，处警告或者五十元罚款。"""),
        LawArticle("第四十三条", "", """违反本条例第二十六条第一款规定，擅自停放电动自行车或者为电动自行车充电的，由消防救援机构责令改正；妨碍安全疏散或者消防车通行的，对单位处五千元以上五万元以下罚款，对个人处警告或者一百元以上五百元以下罚款；违反用电安全要求的，按照有关法律、法规规定处理。"""),
        LawArticle("第四十四条", "", """违反本条例第三十一条第三款规定，对违规停放车辆未及时清理的，由城市管理部门责令改正；拒不改正的，处一千元以上一万元以下罚款。"""),
        LawArticle("第四十五条", "", """公安机关交通管理部门依法通过电子技术监控设备收集、固定非机动车道路交通违法行为证据，依法可以处罚的，应当将电子技术监控设备记录的道路交通安全违法行为信息通知电动自行车所有人、管理人，并告知其在三十日内接受处理；电动自行车所有人、管理人将电动自行车交由他人驾驶的，应当通知驾驶人按照规定期限接受处理；逾期不接受处理，电动自行车仍然上道路行驶，被发现后拒绝接受罚款处罚的，公安机关交通管理部门可以依法扣留车辆。当事人接受处理后，公安机关交通管理部门应当及时返还被扣留的电动自行车。"""),
        LawArticle("第四十六条", "", """依法被扣留的电动自行车，当事人提供被扣留车辆合法证明、补办相应手续或者接受相应处罚的，公安机关交通管理部门应当及时返还；三十日内没有提供被扣留车辆合法证明或者补办相应手续，或者不前来接受处理，经公安机关交通管理部门通知并且经公告三个月仍不前来接受处理的，由公安机关交通管理部门依法处理。"""),
        LawArticle("第四十七条", "", """违反本条例规定的行为，法律、行政法规有行政处罚规定的，从其规定；构成犯罪的，依法追究刑事责任。"""),
        LawArticle("第四十八条", "", """依法应当在公安机关交通管理部门登记，取得机动车号牌的电动轻便摩托车、电动摩托车的管理，依照道路交通安全法律、行政法规关于机动车管理的有关规定执行。"""),
        LawArticle("第四十九条", "", """本条例自2023年3月1日起施行。"""),
    )
)

val LF2_ANHUI_IMPLEMENTATION: LawBook = LawBook(
    id = "anhui_implementation",
    name = "安徽省实施〈中华人民共和国道路交通安全法〉办法（修正）",
    articlesCount = 87,
    chapters = 8,
    intro = """2005年10月21日通过，2006年1月1日施行，2012年10月19日修正（修正版2013年1月1日施行），现行有效。安徽省道路交通安全地方性实施办法，全文收录（共87条·8章）。来源：安徽省人大常委会公布文本。""",
    articles = listOf(
        LawArticle("第一条", "", """根据《中华人民共和国道路交通安全法》、《中华人民共和国道路交通安全法实施条例》，结合本省实际，制定本办法。"""),
        LawArticle("第二条", "", """本办法适用于本省行政区域内的车辆驾驶人、行人、乘车人以及与道路交通活动有关的单位和个人。"""),
        LawArticle("第三条", "", """县级以上人民政府应当加强道路交通安全工作，制定道路交通安全规划，表彰和奖励在道路交通安全工作中作出突出贡献的单位和个人。各级人民政府应当经常进行道路交通安全教育，提高公民的道路交通安全意识。"""),
        LawArticle("第四条", "", """县级以上人民政府公安机关交通管理部门负责本行政区域内的道路交通安全管理工作。安全生产监督、交通运输、住房城乡建设、城乡规划、城市管理（市容）、农业（农业机械）、卫生、新闻、出版、广播、电视等部门应当按照各自职责，做好道路交通安全的有关工作。"""),
        LawArticle("第五条", "", """公安机关交通管理部门及其交通警察应当依法履行职责，严格、公正、文明执法。公安机关交通管理部门及其交通警察应当模范遵守道路交通安全法律、法规。"""),
        LawArticle("第六条", "", """县级以上人民政府应当建立并落实道路交通安全管理责任制，将道路交通安全管理工作列入安全生产考核，定期组织评价交通安全状况。乡（镇）人民政府、街道办事处应当督促辖区内单位落实道路交通安全管理责任制，及时消除安全隐患。"""),
        LawArticle("第七条", "", """县级以上人民政府应当制定应对重特大交通事故以及自然灾害、恶劣气象条件等可能影响道路交通安全的突发事件的应急预案。公安、安全生产监督、交通运输、卫生等部门和收费公路经营者，应当根据相关应急预案制定具体实施方案。"""),
        LawArticle("第八条", "", """公安机关交通管理部门应当依法实施车辆登记，考核机动车驾驶人，管理道路交通秩序，处理道路交通事故，查处道路交通违法行为。安全生产监督管理部门应当依法实施道路交通安全监督，协调各部门加强道路交通安全工作，检查道路交通安全责任制落实情况，督促、协调相关部门对危险路段进行整改，组织重特大交通事故的调查处理工作。交通运输部门应当依法实施对道路客运和货运企业、机动车维修经营企业、驾驶人培训单位的资格管理，会同有关部门合理规划城市公交线路、站点及停车场，监督公路的建设、维护、经营和管理单位依职责做好公路交通安全设施的设置、维护和管理。住房城乡建设、城乡规划、城市管理（市容）等部门应当依法实施城市道路、桥梁、停车场和道路配套设施的规划、设计、建设，监督城市道路的建设、维护和管理单位依职责做好城市道路交通安全设施的设置、维护和管理，加强对城市道路占用、挖掘等行为的管理；根据交通需求，制定城市综合交通规划；加强市容市貌管理，清理违法占道、违法设置广告和违法建筑物、构筑物。农业（农业机械）主管部门应当依法实施对拖拉机的登记、检验，加强对拖拉机驾驶人培训学校的资格管理和拖拉机驾驶人的安全教育，建立健全教练员和考试员考核制度，负责拖拉机驾驶人考试、发证和审验工作。卫生主管部门应当加强交通事故医疗救治工作的组织管理，建立完善交通事故医疗救治快速反应机制。公安机关交通管理部门、农业（农业机械）主管部门应当建立拖拉机信息共享机制，定期通报拖拉机登记、安全技术检验、驾驶证发放和对拖拉机驾驶人的违法行为处罚情况。公安机关交通管理部门、交通运输部门应当依法查处饮酒驾驶、疲劳驾驶和超员、超载、超限、超速运输等道路交通违法行为。"""),
        LawArticle("第九条", "", """国家机关、社会团体、企业事业单位和其他社会组织，应当做好本单位人员的交通安全教育和车辆管理工作，建立健全内部交通安全责任制，履行下列道路交通安全防范义务：（一）建立本单位所属机动车的使用、保养、维修、检验制度，制定机动车报废具体办法，依法办理机动车第三者责任强制保险；（二）教育本单位人员遵守道路交通安全法律、法规，建立对本单位专职机动车驾驶人行车安全的考核制度；（三）雇用驾驶人驾驶机动车的，应当对驾驶人进行资格审查和道路交通安全考核，建立档案；（四）发现本单位机动车驾驶人吸食、注射毒品的，应当向公安机关交通管理部门报告。单位设置门岗、广告和标示牌等，不得影响道路交通安全、畅通。"""),
        LawArticle("第十条", "", """报刊、广播、电视等新闻媒体应当加强对社会公众的交通安全教育，定期发布交通安全公益广告，宣传交通安全知识，及时报道道路交通安全信息和公安机关交通管理部门采取的交通管制措施。"""),
        LawArticle("第十一条", "", """机动车安全技术检验机构应当遵守下列规定：（一）执行机动车国家安全技术标准；（二）按照规定项目和方法检验机动车；（三）使用经法定机构检测、鉴定合格的检测装置（仪器）；（四）建立检验车辆的安全技术档案。公安机关交通管理部门应当在机动车安全技术检验机构安装与机动车安全技术检验系统联网的监控设施，对机动车安全技术检验进行全程监控，实现检验数据同步自动传输。"""),
        LawArticle("第十二条", "", """机动车回收企业在回收报废机动车时，应当登记报废车辆所有人身份证明和车辆号牌、发动机号码、车架号码等信息，并向当事人提供车辆报废证明。机动车回收企业应当在公安机关交通管理部门的监督下，对报废的大型客车、货车及其他营运车辆进行解体。"""),
        LawArticle("第十三条", "", """机动车维修单位承修外观损坏的车辆时，应当登记送修人身份证明及车辆号牌、发动机号码、车架号码，记录外观损坏部位和损坏程度。保存登记资料不少于六个月。发现有交通事故逃逸嫌疑的车辆，应当立即报告公安机关交通管理部门。"""),
        LawArticle("第十四条", "", """设区的市、县（市）人民政府公安机关交通管理部门根据道路交通安全管理工作的需要，可以聘用道路交通安全协管员，协助交通警察维护道路交通秩序，疏导交通。道路交通安全协管员不得实施行政处罚和行政强制措施。"""),
        LawArticle("第十五条", "", """电动自行车、残疾人机动轮椅车等非机动车的登记种类，由省人民政府规定。"""),
        LawArticle("第十六条", "", """设区的市人民政府可以根据本地经济发展和环境、道路交通安全状况，发展公共交通，控制摩托车、低速载货汽车、三轮汽车和出租车的发展。具体控制办法在制定前，应当公开听取社会意见。"""),
        LawArticle("第十七条", "", """机动车号牌可以采取计算机选号的方式发放。"""),
        LawArticle("第十八条", "", """上道路行驶的机动车，不得有下列情形：（一）号牌未安装在机动车前后的规定位置或者倒置、折叠、重叠；（二）大型、中型客车，载货汽车及挂车车厢后部未喷涂或者未悬挂本车号牌放大三倍以上的反光号码；（三）总质量在三点五吨以上的货车、挂车未按照国家标准安装侧面及后下部防护装置；（四）安装、使用妨碍交通安全的光电设备、高音喇叭、大功率音响。"""),
        LawArticle("第十九条", "", """教练车应当符合安全技术标准，领取公安机关交通管理部门核发的教练车号牌和行驶证。在道路上学习驾驶，应当按县级以上公安机关交通管理部门指定的路线、时间进行。"""),
        LawArticle("第二十条", "", """应当报废的机动车，机动车所有人在办理新增机动车注册登记前，应当办理报废的机动车注销登记手续。"""),
        LawArticle("第二十一条", "", """实行机动车驾驶人交通安全信息记录制度。具体办法由省人民政府制定。"""),
        LawArticle("第二十二条", "", """道路经营管理者应当保障道路完好，根据道路等级、交通流量、安全状况以及交通管理的需要，按照国家标准在道路上设置和完善相应的交通安全设施。新建、改建、扩建道路，应当按照国家标准同步规划、设计、建设交通安全设施，并按照国家有关规定进行验收。交通安全设施未经验收或者验收不合格的，道路不得交付使用。"""),
        LawArticle("第二十三条", "", """城市道路、公共停车场（库）及道路配套设施的规划、设计、建设和竣工验收，应当征求公安机关交通管理部门的意见。公共停车场（库）应当在便利位置设置供残疾人机动轮椅车停放的泊位。公共停车场（库）不得擅自停止使用或者改作他用。"""),
        LawArticle("第二十四条", "", """新建、改建、扩建文化、体育场（馆）、学校、商业街区、居住区以及其他重大建设项目，城市规划行政主管部门在审批时应当征求公安机关交通管理等部门的意见，不符合道路交通安全、畅通要求的，应当进行调整。"""),
        LawArticle("第二十五条", "", """公安机关交通管理部门可以根据交通状况在城市中心城区的道路范围内合理设置出租车临时停靠站（位），方便出租车上下客。设置出租车临时停靠站（位），应当征求出租车管理部门的意见。在设有出租车临时停靠站（位）的道路上，出租车不得在站点外等客或者上下客，也不得在临时停靠站（位）内滞留。"""),
        LawArticle("第二十六条", "", """在不影响城市交通、景观、土地使用等情况下，经城市规划行政主管部门同意，公安机关交通管理部门可以在城市道路范围内施划停车泊位。城市交通、景观、土地使用等情况发生变化时，公安机关交通管理部门应当在征求城市规划行政主管部门意见后及时撤除停车泊位。因紧急情况或者举行大型活动，公安机关交通管理部门可以在道路范围内确定临时停车区。"""),
        LawArticle("第二十七条", "", """高速公路交通安全设施、服务区以及公安机关交通管理部门高速公路安全管理机构的办公用房应当与高速公路同时规划、设计、施工、验收与投入使用。公安机关交通管理部门高速公路安全管理机构办公用房，可以按照所有权与使用权分离的原则安排使用，具体由省人民政府确定。"""),
        LawArticle("第二十八条", "", """高速公路经营者、管理者应当保证高速公路交通安全设施齐全有效。公安机关交通管理部门可以通过高速公路的技术监控设施了解过往车辆的情况。公路经营者、管理者在遇有沙尘、冰雹、雨、雪、雾、结冰等气象条件，以及焚烧秸秆产生烟雾等影响通行的情况时，应当通过电子显示屏、标示牌等多种形式，及时发布预警信息。"""),
        LawArticle("第二十九条", "", """因道路改建、养护施工需要中断高速公路、国道、省道交通的，应当征求省公安机关交通管理部门的意见；需要半幅封闭的，应当征求设区的市公安机关交通管理部门的意见。公安机关交通管理部门应当及时采取措施，疏导交通，维护道路交通秩序。遇有交通堵塞或者其他紧急情况时，公安机关交通管理部门可以要求暂时停止道路施工、作业，临时恢复通行。"""),
        LawArticle("第三十条", "", """公路、城市道路的交叉路口，未设置交通信号灯的，应当规范设置让行交通标志或者交通标线。学校、幼儿园、医院、养老院门前的道路，没有行人过街设施的，应当施划人行横道线，设置指示标志。"""),
        LawArticle("第三十一条", "", """乡村、集镇、居住区以及其他组织和个人自建的道路，应当按照国家有关标准设置交通安全设施。在单位管辖范围内，限制社会车辆通行的路段，管理单位设置交通安全设施应当符合国家有关标准。设置时，可以要求公安机关交通管理部门进行指导。"""),
        LawArticle("第三十二条", "", """在没有划分机动车道、非机动车道、人行道的道路上，机动车在道路中间通行，非机动车靠右侧通行，行人应当靠边通行。从道路边缘线算起，行人通行路面宽度不超过一米，自行车不超过一点五米，其他非机动车不超过二点二米。"""),
        LawArticle("第三十三条", "", """在同方向划有三条机动车道的道路上，机动车道可以划分为快速车道、常速车道、慢速车道。左侧为快速车道，右侧为慢速车道，中间为常速车道。同方向有三条以上机动车道的，可以增设快速车道或者常速车道。"""),
        LawArticle("第三十四条", "", """机动车按下列规定分道行驶：（一）小型客车在快速车道或者常速车道行驶；（二）摩托车、低速载货汽车、三轮汽车、拖拉机、轮式自行机械车在慢速车道行驶；（三）其他机动车在慢速车道或者常速车道行驶；（四）常速车道的机动车，在不妨碍小型客车正常行驶时，可以借道超车。在道路划设的公交专用车道内，在规定的时间内，除公共汽车和校车外，其他机动车不得在公交专用车道内行驶；遇交通管制等特殊情况时，按照交通警察指挥或者交通标志指示，可以借用公交专用车道行驶。公交专用车道前方有障碍时，公共汽车、校车可以临时借用相邻车道。借道通行的车辆，应当让在其本道内行驶的车辆或者行人优先通行。借道前，须停车或者减速观望，确认安全后，方可通行。通行时应当迅速通过，不得滞留。机动车变更车道，不得一次连续变更两条以上机动车道。变更车道时，应当提前五十米开启转向灯，在高速公路上应当提前一百五十米开启转向灯。"""),
        LawArticle("第三十五条", "", """机动车通过没有交通信号的交叉路口，除遵守《中华人民共和国道路交通安全法实施条例》第五十二条的规定外，还应当遵守下列规定：（一）机动车让已经进入路口的非机动车、行人先行；（二）货运机动车让客车先行；（三）同类车辆，大型车让小型车先行；（四）低速汽车、三轮汽车、摩托车、拖拉机、轮式自行机械车让其他机动车先行。"""),
        LawArticle("第三十六条", "", """低速载货汽车、三轮汽车、拖拉机不得在下列道路上通行：（一）大中城市中心城区道路；（二）高速公路；（三）县级以上人民政府公安机关明令禁止通行的道路。低速载货汽车、三轮汽车运输农副产品，需要进入大中城市中心城区道路通行，应当按照公安机关交通管理部门指定的线路、时间通行。"""),
        LawArticle("第三十七条", "", """机动车在道路上临时停放时，应当遵守下列规定：（一）在路面宽度不足九米的道路上，不得并列双向停车；（二）在划有停车泊位的路段，应当在停车泊位内停放；（三）车身右边缘距离道路边缘不超过零点五米，沿行驶方向停放。夜间或者在风、雪、雨、雾等低能见度气象条件下，机动车临时停车的，除遵守前款规定外，还应当开启危险报警闪光灯、示廓灯、后尾灯。"""),
        LawArticle("第三十八条", "", """机动车上道路行驶不得超过限速标志、标线标明的速度；没有限速标志、标线的，应当遵守下列规定：（一）同方向划有二条以上机动车道的道路，城市道路最高时速为六十公里，公路最高时速为八十公里；（二）同方向只有一条机动车道的，铰接式客车和附载作业人员的货车、全挂拖斗车、低速载货汽车、三轮摩托车在城市道路上的最高时速为三十公里，公路上的最高时速为五十公里；（三）两轮摩托车在有道路中心线的道路上，城市道路最高时速为四十公里，公路为六十公里；在没有道路中心线的道路上，城市道路最高时速为三十公里，公路为四十公里；（四）三轮汽车、轻便摩托车的最高时速为三十公里，拖拉机的最高时速为二十公里。"""),
        LawArticle("第三十九条", "", """公共汽车进出停靠站应当遵守下列规定：（一）有停车区域的，停靠在停车区域内；未划设停车区域的，应当在停靠站距离道路边缘零点五米以内单列停车；（二）暂时不能进入停靠站的，在最右侧机动车道等候进站，不得开门上下客；（三）驶离停靠站时，依次单列行驶。"""),
        LawArticle("第四十条", "", """机动车在行驶中发生交通事故或者故障的，应当立即停车，按照规定开启危险报警闪光灯，设置警告标志；除抢救伤员、灭火等紧急情况外，驾驶人、乘车人应当迅速离开车辆和车行道，转移至附近安全地带等候。"""),
        LawArticle("第四十一条", "", """机动车驾驶人不得疲劳驾驶机动车。用于公路营运的载客汽车、危险货物运输车辆、重型载货汽车、半挂牵引车应当按照规定安装使用符合国家标准的行驶记录仪。机动车驾驶人驾驶机动车，一般每二小时停车休息一次，休息时间不少于十分钟；连续驾车行驶四小时的，应当停车休息，休息时间不少于二十分钟。推行长途客运车辆凌晨二时至五时停止运行或者实行接驳运输。"""),
        LawArticle("第四十二条", "", """驾驶非机动车应当遵守下列规定：（一）不得在机动车辆之间穿行；（二）不得在车行道上停车滞留；（三）有转向灯的，转弯时应当提前开启转向灯；（四）自行车在城市道路上行驶时，可以搭载一名十二周岁以下的未成年人；搭载学龄前儿童的，应当使用安全座椅；（五）驾驶自行车、三轮车必须年满十二周岁，驾驶电动自行车、残疾人机动轮椅车必须年满十六周岁。"""),
        LawArticle("第四十三条", "", """乘车人应当遵守下列规定：（一）乘坐公共汽车和公路客运汽车，在停靠站或者指定地点依次候车，待车停稳后，先下后上；（二）不得有强迫驾驶人违法驾驶、与驾驶人闲谈嬉闹等影响安全驾驶的行为；（三）不得在车行道上等候、搭乘车辆或者堆放物品；（四）乘坐附载作业人员的货车时，不得站立或者坐在车厢栏板上；（五）乘坐两轮摩托车时，应当在驾驶人座后正向骑坐。"""),
        LawArticle("第四十四条", "", """高速公路经营者、管理者发现行人、非机动车、拖拉机、轮式专用机械车、铰接式客车、全挂拖斗车以及其他设计最高时速低于七十公里的机动车从收费站或者服务区进入高速公路的，应当配合公安机关交通管理部门予以阻止。"""),
        LawArticle("第四十五条", "", """在高速公路上行驶的车辆，除因车辆出现故障、发生交通事故等紧急情况必须停车外，不得停车、停车上下人员或者装卸货物。"""),
        LawArticle("第四十六条", "", """发生重特大交通事故，当地人民政府应当立即实施应急预案，开展紧急救援。"""),
        LawArticle("第四十七条", "", """机动车驾驶人发生交通事故后逃逸的，乘车人、车辆所有人和其他事故现场目击人员、知情人员应当向公安机关交通管理部门或者交通警察举报。因调查交通事故的需要，公安机关交通管理部门可以查阅道路收费站、渡口以及其他有关单位记载过往车辆信息的资料，有关单位应当及时无偿提供。"""),
        LawArticle("第四十八条", "", """交通事故现场勘查完毕后，当事人应当按照公安机关交通管理部门的要求，及时将车辆移至不妨碍交通的地方。当事人无力实施或者拒不服从的，公安机关交通管理部门可以指定有关施救单位将车辆移至不妨碍交通的地方，所需费用由当事人承担。"""),
        LawArticle("第四十九条", "", """对交通事故车辆及其行驶速度、痕迹、物品以及现场的道路状况等需要进行一般性检验的，公安机关交通管理部门可以指派本部门专业人员进行；情况复杂的，应当委托具备资质的专业鉴定机构进行检验、鉴定。"""),
        LawArticle("第五十条", "", """公安机关交通管理部门经过调查后，应当根据当事人的行为对发生交通事故所起的作用以及过错的严重程度，确定当事人的责任。交通事故当事人的责任分为全部责任、主要责任、同等责任、次要责任和无责任。交通事故责任的具体确定标准由省公安机关制定，并向社会公布。"""),
        LawArticle("第五十一条", "", """未造成人员伤亡的交通事故，有下列情形之一的，当事人直接向保险公司报告，保险公司应当依法理赔：（一）当事人依法自行协商处理的交通事故；（二）仅造成自身车辆物品损失的单方交通事故。"""),
        LawArticle("第五十二条", "", """机动车之间发生交通事故的，由机动车各方所投保的保险公司在第三者责任强制保险责任限额内赔偿损失；机动车一方或者各方未投保第三者责任强制保险的，应当在其应当投保的责任限额内承担赔偿责任。机动车之间发生交通事故的损失超出第三者责任强制保险责任限额的部分，由有事故责任的一方承担赔偿责任；双方都有事故责任的，按照各自事故责任的比例分担赔偿责任。"""),
        LawArticle("第五十三条", "", """机动车与非机动车驾驶人、行人之间发生交通事故的，由机动车一方所投保的保险公司在第三者责任强制保险责任限额内赔偿损失；机动车一方未投保第三者责任强制保险的，应当在其应当投保的责任限额内承担赔偿责任。"""),
        LawArticle("第五十四条", "", """机动车与非机动车驾驶人、行人之间发生交通事故的损失超出第三者责任强制保险责任限额的部分，机动车一方有事故责任的，由机动车一方按照下列规定承担赔偿责任：（一）机动车一方在交通事故中负全部责任的，承担百分之一百的赔偿责任；（二）机动车一方在交通事故中负主要责任的，承担百分之八十的赔偿责任；（三）机动车一方在交通事故中负同等责任的，承担百分之六十的赔偿责任；（四）机动车一方在交通事故中负次要责任的，承担百分之四十的赔偿责任。"""),
        LawArticle("第五十五条", "", """机动车与非机动车驾驶人、行人之间发生交通事故的损失超出第三者责任强制保险责任限额的部分，有证据证明交通事故是由非机动车驾驶人、行人违反道路交通安全法律、法规造成，机动车驾驶人无事故责任，且已经采取必要处置措施的，按照下列规定承担赔偿责任：（一）在高速公路、高架道路以及其他封闭道路上发生交通事故的，机动车一方承担百分之五的赔偿责任；（二）在其他道路上发生交通事故的，机动车一方承担百分之十的赔偿责任。"""),
        LawArticle("第五十六条", "", """交通事故的损失是由非机动车驾驶人、行人故意造成的，机动车一方不承担赔偿责任。"""),
        LawArticle("第五十七条", "", """公安机关交通管理部门及其交通警察对道路交通安全违法行为，应当及时纠正。对于情节轻微，未影响道路通行的，指出违法行为，给予口头警告后放行。"""),
        LawArticle("第五十八条", "", """公安机关交通管理部门对于道路交通安全违法行为，给予暂扣或者吊销机动车驾驶证、拘留处罚，采取扣留车辆、强制拆除、强制报废等措施的，依照《中华人民共和国道路交通安全法》、《中华人民共和国道路交通安全法实施条例》的规定执行。"""),
        LawArticle("第五十九条", "", """行人有下列行为之一的，处警告或者五十元罚款：（一）违反交通信号的；（二）跨越、倚坐道路隔离设施的；（三）追车、扒车、强行拦车的；（四）抛物击车、进入高速公路的。"""),
        LawArticle("第六十条", "", """乘车人有下列行为之一的，处警告或者五十元罚款：（一）未按规定使用安全带的；（二）机动车行驶中，影响驾驶人安全驾驶的；（三）乘坐两轮摩托车未按规定系戴头盔或者非正向骑坐的；（四）携带危险物品的。"""),
        LawArticle("第六十一条", "", """非机动车驾驶人有下列行为之一的，处警告或者五十元罚款：（一）醉酒驾驶非机动车的；（二）非下肢残疾的人驾驶残疾人机动轮椅车的；（三）三轮车、自行车加装动力装置的；（四）进入高速公路的；（五）进入城市快速路的；（六）违反规定载人的；（七）违反交通信号规定的；（八）逆向行驶的。有前款第（一）至（三）项情形之一的，公安机关交通管理部门应当扣留非机动车，待违法状态消除或者当事人补办相应手续后予以放行。驾驶非机动车违反交通管制的规定强行通行，不听劝阻的，处二百元罚款。"""),
        LawArticle("第六十二条", "", """机动车驾驶人有下列行为之一的，处警告或者五十元罚款：（一）在实习期内驾驶机动车不按规定粘贴或者悬挂统一式样的实习标志的；（二）驾驶机动车拨打、接听手持电话的；（三）在机动车驾驶室的前后窗范围内悬挂、放置妨碍驾驶人视线的物品的；（四）驾驶机动车向道路上抛撒物品的；（五）驾驶摩托车手离车把或者在车把上悬挂物品的；（六）驾驶摩托车未按规定系戴安全头盔的；（七）驾驶拖拉机违反交通信号规定的；（八）驾驶低速载货汽车、三轮汽车、拖拉机违反规定驶入大中城市中心城区内道路的。"""),
        LawArticle("第六十三条", "", """机动车驾驶人有下列行为之一的，处一百元罚款：（一）未随车携带行驶证、驾驶证的；（二）不按规定车道行驶的；（三）不按规定让行、掉头、转弯的；（四）违反学习驾驶规定的；（五）驶入禁止通行道路的；（六）下陡坡时熄火或者空档滑行的；（七）不按规定使用灯光的；（八）特种车辆违反规定使用警报器或者标志灯具的；（九）非特种车辆喷涂特种车辆标志的；（十）违反规定载货的；（十一）驾驶安全设施不全或者机件不符合技术标准等具有安全隐患的机动车的；（十二）违反规定使用专用车道的；（十三）在道路上车辆发生故障、交通事故停车后，不按规定使用警示灯光或者设置警告标志的；（十四）未按规定使用安全带的；（十五）违反规定停放、临时停车且驾驶人不在现场或者驾驶人虽在现场拒绝立即驶离，妨碍其他车辆、行人通行的；（十六）在设置出租车临时停靠站（位）的路段，出租车在站（位）外等客、上下客或者在站（位）内滞留等客的；（十七）除本人无法移动外，未及时将故障车移至不妨碍交通的地方停放的。"""),
        LawArticle("第六十四条", "", """机动车驾驶人有下列行为之一的，处二百元罚款：（一）故意遮挡、污损或者未按规定安装机动车号牌的；（二）重型、中型载货汽车及其挂车的车身或者车厢后部未按规定喷涂放大的牌号，或者放大的牌号不清晰的；（三）载货汽车、挂车，未按规定粘贴车身反光标识的；（四）载货汽车、挂车，未按规定安装侧面及后下部防护装置的；（五）未放置机动车检验合格标志、保险标志的；（六）重型载货汽车进入有明确标示禁止通行的高架桥等道路的；（七）逆向行驶的；（八）违反交通信号规定的；（九）违反规定超车、会车、倒车的；（十）未按规定安装、使用行驶记录仪的；（十一）连续驾驶机动车超过四小时未停车休息或者停车休息时间少于二十分钟的；（十二）驾驶证丢失、损毁、超过有效期或者被依法扣留、暂扣期间以及道路交通安全违法行为累积记分分值达到十二分，仍驾驶机动车的；（十三）服用国家管制的精神药品、麻醉药品或者患有妨碍安全驾驶的疾病仍继续驾驶的；（十四）违反规定运载危险物品的；（十五）未取得机动车号牌或者临时通行牌证逾期仍上道路行驶的；（十六）发生轻微财产损失的交通事故，依法应当自行撤离现场而未撤离，造成交通堵塞的。运输单位的驾驶人驾驶营运载客汽车、危险货物运输车辆、重型载货汽车、半挂牵引车，有前款第十一项所列行为，经处罚未改正的，对运输单位直接负责的主管人员处二千元以上五千元以下罚款。"""),
        LawArticle("第六十五条", "", """机动车驾驶人驾车在高速公路上有下列行为之一的，处二百元罚款：（一）违反规定停车的；（二）倒车、逆行、穿越中央分隔带掉头的；（三）试车或者学习驾驶机动车的；（四）正常情况下低于规定最低时速行驶的；（五）在隧道内超车的；（六）禁止进入高速公路的机动车驶入高速公路的；（七）载货汽车车厢或者两轮摩托车载人的；（八）停车上下人员或者装卸货物的；（九）不按规定分道行驶的。机动车驾驶人在高速公路上有违反道路交通安全法律、法规关于道路通行规定其他行为的，处警告或者一百元罚款。"""),
        LawArticle("第六十六条", "", """有下列行为的，按以下规定处罚：（一）未取得机动车驾驶证或者机动车驾驶证被吊销仍然驾驶摩托车、拖拉机的，处三百元罚款；（二）未取得机动车驾驶证或者机动车驾驶证被吊销仍然驾驶低速载货汽车、三轮汽车的，处五百元罚款；（三）未取得机动车驾驶证或者机动车驾驶证被吊销仍然驾驶其他机动车的，处一千元罚款；（四）机动车驾驶人未取得机动车驾驶证、机动车驾驶证被吊销、暂扣期间驾驶机动车从事营运的，处二千元罚款。将机动车交由未取得机动车驾驶证或者机动车驾驶证被吊销、暂扣的人驾驶的，处五百元罚款。驾驶与驾驶证载明的准驾车型不相符合的车辆的，按未取得机动车驾驶证给予罚款。"""),
        LawArticle("第六十七条", "", """有下列行为的，按以下规定处罚：（一）驾驶拼装或者已达到报废标准的摩托车、拖拉机在道路上行驶的，对驾驶人处三百元罚款；（二）驾驶拼装或者已达到报废标准的低速载货汽车、三轮汽车上道路行驶的，对驾驶人处五百元罚款；（三）驾驶拼装或者已达到报废标准的其他机动车上道路行驶的，对驾驶人处一千元罚款；（四）驾驶拼装或者已达到报废标准的机动车在道路上从事客运的，对驾驶人处二千元罚款。"""),
        LawArticle("第六十八条", "", """伪造、变造或者使用伪造、变造的机动车登记证书、号牌、行驶证、驾驶证的，由公安机关交通管理部门予以收缴，扣留该机动车，处十五日以下拘留，并处五千元罚款；构成犯罪的，依法追究刑事责任。伪造、变造或者使用伪造、变造的检验合格标志、保险标志的，由公安机关交通管理部门予以收缴，扣留该机动车，处十日以下拘留，并处二千元罚款；构成犯罪的，依法追究刑事责任。使用其他车辆的机动车登记证书、号牌、行驶证、检验合格标志、保险标志的，由公安机关交通管理部门予以收缴，扣留该机动车，处四千元罚款。"""),
        LawArticle("第六十九条", "", """饮酒后驾驶机动车的，处暂扣六个月机动车驾驶证，并处一千五百元罚款。因饮酒后驾驶机动车被处罚，再次饮酒后驾驶机动车的，处十日以下拘留，并处二千元罚款，吊销机动车驾驶证。醉酒驾驶机动车的，由公安机关交通管理部门约束至酒醒，吊销机动车驾驶证，依法追究刑事责任，五年内不得取得机动车驾驶证。饮酒后驾驶营运机动车的，处十五日拘留，并处五千元罚款，吊销机动车驾驶证，五年内不得取得机动车驾驶证。醉酒驾驶营运机动车的，由公安机关交通管理部门约束至酒醒，吊销机动车驾驶证，依法追究刑事责任；十年内不得取得机动车驾驶证，取得机动车驾驶证后，不得驾驶营运机动车。饮酒后或者醉酒驾驶机动车发生重大交通事故，构成犯罪的，依法追究刑事责任，并由公安机关交通管理部门吊销机动车驾驶证，终生不得重新取得机动车驾驶证。"""),
        LawArticle("第七十条", "", """驾驶机动车超过规定时速的，按以下规定处罚：（一）超过规定时速百分之十以上不到百分之二十的，处五十元罚款；在高速公路上的处一百元罚款；（二）超过规定时速百分之二十以上不到百分之五十的，处一百元罚款；在高速公路上的处二百元罚款；（三）超过规定时速百分之五十以上不到百分之一百的，处五百元罚款；在高速公路上的处一千元罚款；（四）超过规定时速百分之一百以上的，处二千元罚款。"""),
        LawArticle("第七十一条", "", """公路客运车辆有下列情形的，按下列规定处罚：（一）超过额定乘员不足百分之二十的，处二百元罚款；（二）超过额定乘员百分之二十以上不足百分之五十或者违反规定载货的，处五百元罚款；（三）超过额定乘员百分之五十以上不足百分之一百的，处一千元罚款；（四）超过额定乘员百分之一百以上的，处二千元罚款。货运车辆有下列情形的，按下列规定处罚：（一）超过核定载质量不足百分之三十的，处二百元罚款；（二）超过核定载质量百分之三十以上不足百分之一百或者违反规定载人的，处五百元罚款；（三）超过核定载质量百分之一百以上的，处一千元罚款；（四）以营利为目的违反规定载人的，处二千元罚款。运输单位的车辆有本条第一款、第二款规定的情形，经处罚未改正的，对直接负责的主管人员处三千元罚款；情节严重的，处五千元罚款。"""),
        LawArticle("第七十二条", "", """机动车驾驶人违反交通管制的规定强行通行，不听劝阻的，处五百元以上一千元以下罚款；情节严重的，处一千元以上二千元以下罚款。"""),
        LawArticle("第七十三条", "", """强迫机动车驾驶人违反道路交通安全法律、法规和机动车安全驾驶要求驾驶机动车，造成交通事故，尚不构成犯罪的，处一千元以上二千元以下罚款。"""),
        LawArticle("第七十四条", "", """驾驶非机动车造成交通事故后逃逸，尚不构成犯罪的，处五百元罚款。驾驶机动车造成交通事故后逃逸，尚不构成犯罪的，按照以下规定处罚：（一）仅造成财产损失的，处一千元罚款；（二）造成人员伤害的，处二千元罚款。"""),
        LawArticle("第七十五条", "", """非法拦截、扣留机动车辆，不听劝阻，造成交通严重阻塞或者较大财产损失的，处五百元以上一千元以下罚款；情节严重的，处一千元以上二千元以下罚款。"""),
        LawArticle("第七十六条", "", """故意损毁、移动、涂改交通设施，造成危害后果的，处五百元以上一千元以下罚款；情节严重，尚不构成犯罪的，处一千元以上二千元以下罚款。"""),
        LawArticle("第七十七条", "", """在道路两侧及隔离带上种植树木、其他植物或者设置广告牌、管线等，遮挡路灯、交通信号灯、交通标志，妨碍安全视距的，由公安机关交通管理部门责令行为人排除妨碍。拒不执行的，处五百元以上一千元以下罚款；情节严重的，处一千元以上二千元以下罚款，并强制排除妨碍，所需费用由行为人负担。"""),
        LawArticle("第七十八条", "", """机动车安全技术检验机构不按照机动车国家安全技术标准进行检验，出具虚假检验结果的，处所收检验费用的八倍罚款。"""),
        LawArticle("第七十九条", "", """机动车所有人、管理人未按照国家规定投保机动车第三者责任强制保险的，由公安机关交通管理部门扣留车辆至依照规定投保后，并处依照规定投保最低责任限额应缴纳的保险费的二倍罚款。"""),
        LawArticle("第八十条", "", """出售已达到报废标准的机动车的，没收违法所得，处销售金额等额的罚款。"""),
        LawArticle("第八十一条", "", """非法安装警报器、标志灯具的，处五百元罚款；情节严重的，处一千元以上二千元以下罚款。"""),
        LawArticle("第八十二条", "", """无机动车驾驶证的人驾驶机动车发生交通事故逃逸，构成犯罪的，终生不得取得机动车驾驶证。"""),
        LawArticle("第八十三条", "", """当事人对行政处罚决定不服的，可以依法申请复议或者提起诉讼；逾期不履行处罚决定的，作出处罚决定的机关可以依法申请人民法院强制执行。"""),
        LawArticle("第八十四条", "", """公安机关交通管理部门以及安全生产监督、交通运输、住房城乡建设、城乡规划、城市管理（市容）、农业（农业机械）、卫生等部门及其工作人员，在道路交通安全管理工作中，滥用职权、徇私舞弊、玩忽职守，由所在单位或者上级主管部门依法给予直接负责的主管人员和直接责任人员行政处分；构成犯罪的，依法追究刑事责任。"""),
        LawArticle("第八十五条", "", """本办法所称交通安全设施，是指交通信号灯、交通标志、交通标线、交通监控、护栏等设施。"""),
        LawArticle("第八十六条", "", """本办法所称借道通行，是指行人在没有划设人行横道的道路上通过车行道，车辆在转弯、会车、超车、掉头、停车时驶入其他道路，包括机动车变更车道、驶入非机动车道或者人行道，非机动车驶入机动车道或者人行道。"""),
        LawArticle("第八十七条", "", """本办法自2006年1月1日起施行。"""),
    )
)

val LF2_DRUNK_DRIVING_OPINION: LawBook = LawBook(
    id = "drunk_driving_opinion",
    name = "最高法、最高检、公安部、司法部关于办理醉酒危险驾驶刑事案件的意见",
    articlesCount = 30,
    chapters = 0,
    intro = """2023年12月13日印发，2023年12月28日施行，共30条。同时废止2013年“两高一部”醉驾意见。是当前办理醉驾（危险驾驶）刑事案件的统一规范，全文收录。来源：最高人民检察院/公安部。""",
    articles = listOf(
        LawArticle("第一条", "", """人民法院、人民检察院、公安机关办理醉驾案件，应当坚持分工负责，互相配合，互相制约，坚持正确适用法律，坚持证据裁判原则，严格执法，公正司法，提高办案效率，实现政治效果、法律效果和社会效果的有机统一。人民检察院依法对醉驾案件办理活动实行法律监督。"""),
        LawArticle("第二条", "", """人民法院、人民检察院、公安机关办理醉驾案件，应当全面准确贯彻宽严相济刑事政策，根据案件的具体情节，实行区别对待，做到该宽则宽，当严则严，罚当其罪。"""),
        LawArticle("第三条", "", """人民法院、人民检察院、公安机关和司法行政机关应当坚持惩治与预防相结合，采取多种方式强化综合治理、诉源治理，从源头上预防和减少酒后驾驶行为发生。二、立案与侦查"""),
        LawArticle("第四条", "", """在道路上驾驶机动车，经呼气酒精含量检测，显示血液酒精含量达到80毫克/100毫升以上的，公安机关应当依照刑事诉讼法和本意见的规定决定是否立案。对情节显著轻微、危害不大，不认为是犯罪的，不予立案。公安机关应当及时提取犯罪嫌疑人血液样本送检。认定犯罪嫌疑人是否醉酒，主要以血液酒精含量鉴定意见作为依据。犯罪嫌疑人经呼气酒精含量检测，显示血液酒精含量达到80毫克/100毫升以上，在提取血液样本前脱逃或者找人顶替的，可以以呼气酒精含量检测结果作为认定其醉酒的依据。犯罪嫌疑人在公安机关依法检查时或者发生道路交通事故后，为逃避法律追究，在呼气酒精含量检测或者提取血液样本前故意饮酒的，可以以查获后血液酒精含量鉴定意见作为认定其醉酒的依据。"""),
        LawArticle("第五条", "", """醉驾案件中“道路”“机动车”的认定适用道路交通安全法有关“道路”“机动车”的规定。对机关、企事业单位、厂矿、校园、居民小区等单位管辖范围内的路段是否认定为“道路”，应当以其是否具有“公共性”，是否“允许社会机动车通行”作为判断标准。只允许单位内部机动车、特定来访机动车通行的，可以不认定为“道路”。"""),
        LawArticle("第六条", "", """对醉驾犯罪嫌疑人、被告人，根据案件具体情况，可以依法予以拘留或者取保候审。具有下列情形之一的，一般予以取保候审：（一）因本人受伤需要救治的；（二）患有严重疾病，不适宜羁押的；（三）系怀孕或者正在哺乳自己婴儿的妇女；（四）系生活不能自理的人的唯一扶养人；（五）其他需要取保候审的情形。对符合取保候审条件，但犯罪嫌疑人、被告人不能提出保证人，也不交纳保证金的，可以监视居住。对违反取保候审、监视居住规定的犯罪嫌疑人、被告人，情节严重的，可以予以逮捕。"""),
        LawArticle("第七条", "", """办理醉驾案件，应当收集以下证据：（一）证明犯罪嫌疑人情况的证据材料，主要包括人口信息查询记录或者户籍证明等身份证明；驾驶证、驾驶人信息查询记录；犯罪前科记录、曾因饮酒后驾驶机动车被查获或者行政处罚记录、本次交通违法行政处罚决定书等；（二）证明醉酒检测鉴定情况的证据材料，主要包括呼气酒精含量检测结果、呼气酒精含量检测仪标定证书、血液样本提取笔录、鉴定委托书或者鉴定机构接收检材登记材料、血液酒精含量鉴定意见、鉴定意见通知书等；（三）证明机动车情况的证据材料，主要包括机动车行驶证、机动车信息查询记录、机动车照片等；（四）证明现场执法情况的照片，主要包括现场检查机动车、呼气酒精含量检测、提取与封装血液样本等环节的照片，并应当保存相关环节的录音录像资料；（五）犯罪嫌疑人供述和辩解。根据案件具体情况，还应当收集以下证据：（一）犯罪嫌疑人是否饮酒、驾驶机动车有争议的，应当收集同车人员、现场目击证人或者共同饮酒人员等证人证言、饮酒场所及行驶路段监控记录等；（二）道路属性有争议的，应当收集相关管理人员、业主等知情人员证言、管理单位或者有关部门出具的证明等；（三）发生交通事故的，应当收集交通事故认定书、事故路段监控记录、人体损伤程度等鉴定意见、被害人陈述等；（四）可能构成自首的，应当收集犯罪嫌疑人到案经过等材料；（五）其他确有必要收集的证据材料。"""),
        LawArticle("第八条", "", """对犯罪嫌疑人血液样本提取、封装、保管、送检、鉴定等程序，按照公安部、司法部有关道路交通安全违法行为处理程序、鉴定规则等规定执行。公安机关提取、封装血液样本过程应当全程录音录像。血液样本提取、封装应当做好标记和编号，由提取人、封装人、犯罪嫌疑人在血液样本提取笔录上签字。犯罪嫌疑人拒绝签字的，应当注明。提取的血液样本应当及时送往鉴定机构进行血液酒精含量鉴定。因特殊原因不能及时送检的，应当按照有关规范和技术标准保管检材并在五个工作日内送检。鉴定机构应当对血液样品制备和仪器检测过程进行录音录像。鉴定机构应当在收到送检血液样本后三个工作日内，按照有关规范和技术标准进行鉴定并出具血液酒精含量鉴定意见，通知或者送交委托单位。血液酒精含量鉴定意见作为证据使用的，办案单位应当自收到血液酒精含量鉴定意见之日起五个工作日内，书面通知犯罪嫌疑人、被告人、被害人或者其法定代理人。"""),
        LawArticle("第九条", "", """具有下列情形之一，经补正或者作出合理解释的，血液酒精含量鉴定意见可以作为定案的依据；不能补正或者作出合理解释的，应当予以排除：（一）血液样本提取、封装、保管不规范的；（二）未按规定的时间和程序送检、出具鉴定意见的；（三）鉴定过程未按规定同步录音录像的；（四）存在其他瑕疵或者不规范的取证行为的。三、刑事追究"""),
        LawArticle("第十条", "", """醉驾具有下列情形之一，尚不构成其他犯罪的，从重处理：（一）造成交通事故且负事故全部或者主要责任的；（二）造成交通事故后逃逸的；（三）未取得机动车驾驶证驾驶汽车的；（四）严重超员、超载、超速驾驶的；（五）服用国家规定管制的精神药品或者麻醉药品后驾驶的；（六）驾驶机动车从事客运活动且载有乘客的；（七）驾驶机动车从事校车业务且载有师生的；（八）在高速公路上驾驶的；（九）驾驶重型载货汽车的；（十）运输危险化学品、危险货物的；（十一）逃避、阻碍公安机关依法检查的；（十二）实施威胁、打击报复、引诱、贿买证人、鉴定人等人员或者毁灭、伪造证据等妨害司法行为的；（十三）二年内曾因饮酒后驾驶机动车被查获或者受过行政处罚的；（十四）五年内曾因危险驾驶行为被判决有罪或者作相对不起诉的；（十五）其他需要从重处理的情形。"""),
        LawArticle("第十一条", "", """醉驾具有下列情形之一的，从宽处理：（一）自首、坦白、立功的；（二）自愿认罪认罚的；（三）造成交通事故，赔偿损失或者取得谅解的；（四）其他需要从宽处理的情形。"""),
        LawArticle("第十二条", "", """醉驾具有下列情形之一，且不具有本意见第十条规定情形的，可以认定为情节显著轻微、危害不大，依照刑法第十三条、刑事诉讼法第十六条的规定处理：（一）血液酒精含量不满150毫克/100毫升的；（二）出于急救伤病人员等紧急情况驾驶机动车，且不构成紧急避险的；（三）在居民小区、停车场等场所因挪车、停车入位等短距离驾驶机动车的；（四）由他人驾驶至居民小区、停车场等场所短距离接替驾驶停放机动车的，或者为了交由他人驾驶，自居民小区、停车场等场所短距离驶出的；（五）其他情节显著轻微的情形。醉酒后出于急救伤病人员等紧急情况，不得已驾驶机动车，构成紧急避险的，依照刑法第二十一条的规定处理。"""),
        LawArticle("第十三条", "", """对公安机关移送审查起诉的醉驾案件，人民检察院综合考虑犯罪嫌疑人驾驶的动机和目的、醉酒程度、机动车类型、道路情况、行驶时间、速度、距离以及认罪悔罪表现等因素，认为属于犯罪情节轻微的，依照刑法第三十七条、刑事诉讼法第一百七十七条第二款的规定处理。"""),
        LawArticle("第十四条", "", """对符合刑法第七十二条规定的醉驾被告人，依法宣告缓刑。具有下列情形之一的，一般不适用缓刑：（一）造成交通事故致他人轻微伤或者轻伤，且负事故全部或者主要责任的；（二）造成交通事故且负事故全部或者主要责任，未赔偿损失的；（三）造成交通事故后逃逸的；（四）未取得机动车驾驶证驾驶汽车的；（五）血液酒精含量超过180毫克/100毫升的；（六）服用国家规定管制的精神药品或者麻醉药品后驾驶的；（七）采取暴力手段抗拒公安机关依法检查，或者实施妨害司法行为的；（八）五年内曾因饮酒后驾驶机动车被查获或者受过行政处罚的；（九）曾因危险驾驶行为被判决有罪或者作相对不起诉的；（十）其他情节恶劣的情形。"""),
        LawArticle("第十五条", "", """对被告人判处罚金，应当根据醉驾行为、实际损害后果等犯罪情节，综合考虑被告人缴纳罚金的能力，确定与主刑相适应的罚金数额。起刑点一般不应低于道路交通安全法规定的饮酒后驾驶机动车相应情形的罚款数额；每增加一个月拘役，增加一千元至五千元罚金。"""),
        LawArticle("第十六条", "", """醉驾同时构成交通肇事罪、过失以危险方法危害公共安全罪、以危险方法危害公共安全罪等其他犯罪的，依照处罚较重的规定定罪，依法从严追究刑事责任。醉酒驾驶机动车，以暴力、威胁方法阻碍公安机关依法检查，又构成妨害公务罪、袭警罪等其他犯罪的，依照数罪并罚的规定处罚。"""),
        LawArticle("第十七条", "", """犯罪嫌疑人醉驾被现场查获后，经允许离开，再经公安机关通知到案或者主动到案，不认定为自动投案；造成交通事故后保护现场、抢救伤者，向公安机关报告并配合调查的，应当认定为自动投案。"""),
        LawArticle("第十八条", "", """根据本意见第十二条第一款、第十三条、第十四条处理的案件，可以将犯罪嫌疑人、被告人自愿接受安全驾驶教育、从事交通志愿服务、社区公益服务等情况作为作出相关处理的考量因素。"""),
        LawArticle("第十九条", "", """对犯罪嫌疑人、被告人决定不起诉或者免予刑事处罚的，可以根据案件的不同情况，予以训诫或者责令具结悔过、赔礼道歉、赔偿损失，需要给予行政处罚、处分的，移送有关主管机关处理。"""),
        LawArticle("第二十条", "", """醉驾属于严重的饮酒后驾驶机动车行为。血液酒精含量达到80毫克/100毫升以上，公安机关应当在决定不予立案、撤销案件或者移送审查起诉前，给予行为人吊销机动车驾驶证行政处罚。根据本意见第十二条第一款处理的案件，公安机关还应当按照道路交通安全法规定的饮酒后驾驶机动车相应情形，给予行为人罚款、行政拘留的行政处罚。人民法院、人民检察院依据本意见第十二条第一款、第十三条处理的案件，对被不起诉人、被告人需要予以行政处罚的，应当提出检察意见或者司法建议，移送公安机关依照前款规定处理。公安机关应当将处理情况通报人民法院、人民检察院。四、快速办理"""),
        LawArticle("第二十一条", "", """人民法院、人民检察院、公安机关和司法行政机关应当加强协作配合，在遵循法定程序、保障当事人权利的前提下，因地制宜建立健全醉驾案件快速办理机制，简化办案流程，缩短办案期限，实现醉驾案件优质高效办理。"""),
        LawArticle("第二十二条", "", """符合下列条件的醉驾案件，一般应当适用快速办理机制：（一）现场查获，未造成交通事故的；（二）事实清楚，证据确实、充分，法律适用没有争议的；（三）犯罪嫌疑人、被告人自愿认罪认罚的；（四）不具有刑事诉讼法第二百二十三条规定情形的。"""),
        LawArticle("第二十三条", "", """适用快速办理机制办理的醉驾案件，人民法院、人民检察院、公安机关一般应当在立案侦查之日起三十日内完成侦查、起诉、审判工作。"""),
        LawArticle("第二十四条", "", """在侦查或者审查起诉阶段采取取保候审措施的，案件移送至审查起诉或者审判阶段时，取保候审期限尚未届满且符合取保候审条件的，受案机关可以不再重新作出取保候审决定，由公安机关继续执行原取保候审措施。"""),
        LawArticle("第二十五条", "", """对醉驾被告人拟提出缓刑量刑建议或者宣告缓刑的，一般可以不进行调查评估。确有必要的，应当及时委托社区矫正机构或者有关社会组织进行调查评估。受委托方应当及时向委托机关提供调查评估结果。"""),
        LawArticle("第二十六条", "", """适用简易程序、速裁程序的醉驾案件，人民法院、人民检察院、公安机关和司法行政机关可以采取合并式、要素式、表格式等方式简化文书。具备条件的地区，可以通过一体化的网上办案平台流转、送达电子卷宗、法律文书等，实现案件线上办理。五、综合治理"""),
        LawArticle("第二十七条", "", """人民法院、人民检察院、公安机关和司法行政机关应当积极落实普法责任制，加强道路交通安全法治宣传教育，广泛开展普法进机关、进乡村、进社区、进学校、进企业、进单位、进网络工作，引导社会公众培养规则意识，养成守法习惯。"""),
        LawArticle("第二十八条", "", """人民法院、人民检察院、公安机关和司法行政机关应当充分运用司法建议、检察建议、提示函等机制，督促有关部门、企事业单位，加强本单位人员教育管理，加大驾驶培训环节安全驾驶教育，规范代驾行业发展，加强餐饮、娱乐等涉酒场所管理，加大警示提醒力度。"""),
        LawArticle("第二十九条", "", """公安机关、司法行政机关应当根据醉驾服刑人员、社区矫正对象的具体情况，制定有针对性的教育改造、矫正方案，实现分类管理、个别化教育，增强其悔罪意识、法治观念，帮助其成为守法公民。六、附则"""),
        LawArticle("第三十条", "", """本意见自2023年12月28日起施行。《最高人民法院 最高人民检察院 公安部关于办理醉酒驾驶机动车刑事案件适用法律若干问题的意见》（法发〔2013〕15号）同时废止。坚持严格执法、公正司法，加强醉驾综合治理“两高两部”相关部门负责人就发布《关于办理醉酒危险驾驶刑事案件的意见》答记者问发布时间：2023年12月18日12月18日，最高人民法院、最高人民检察院、公安部、司法部联合发布《关于办理醉酒危险驾驶刑事案件的意见》（以下简称《意见》）。《意见》将于2023年12月28日起施行。为准确理解《意见》内容，记者采访了“两高两部”相关部门负责人。问：“两高两部”此次出台《意见》的背景和主要考虑是什么？答：2011年5月，《刑法修正案（八）》增设了危险驾驶罪，在道路上醉酒驾驶机动车（以下简称醉驾）是其中一种危险驾驶行为。最高人民法院、最高人民检察院、公安部于2013年12月印发的《关于办理醉酒驾驶机动车刑事案件适用法律若干问题的意见》（以下简称“2013年意见”），对明确醉驾认定标准、规范案件办理程序起到了积极作用。醉驾入刑以来，各地坚持严格执法、公正司法，依法惩治酒驾醉驾违法犯罪行为，有力维护了人民群众生命财产安全和道路交通安全，酒驾醉驾百车查处率明显下降，酒驾醉驾导致的恶性交通死亡事故大幅减少，“喝酒不开车，开车不喝酒”的法治观念逐步成为社会共识，酒驾醉驾治理成效显著。党的十八大以来，以习近平同志为核心的党中央领导人民续写了经济快速发展和社会长期稳定两大奇迹，人民群众获得感、幸福感、安全感不断增强，执法司法理念、社会治理能力也在与时俱进。如何助力更高水平的平安中国建设，更好地发挥刑罚在社会治理中的作用，更好地落实严格执法、公正司法，各地在依法惩治酒驾醉驾方面进行了有益探索，积累了丰富的司法经验。同时，在醉驾案件办理中也遇到一些新情况、新问题，对“2013年意见”进行补充完善很有必要，条件也已经成熟。为深入贯彻习近平法治思想，根据新形势新变化新要求，积极回应社会关切，在中央政法委组织领导下，最高人民法院、最高人民检察院、公安部、司法部总结各地经验，经深入调研、共同协商，听取司法实务人员和专家学者意见建议，并征求全国人大常委会法制工作委员会意见，制定了《意见》。问：制定《意见》的总体思路是什么？《意见》主要包括哪些内容？答：《意见》落实落细“四个坚持”。坚持人民至上，将维护人民群众生命财产安全置于首位，同时对醉驾情节轻微的初犯给予改过自新的机会。坚持严格执法、公正司法，进一步统一执法司法标准、规范执法办案，做到有法可依、有法必依、执法必严、违法必究。处理具体案件实事求是、不枉不纵、宽严相济、法理情融合，确保办案取得良好的政治效果、法律效果和社会效果。坚持系统思维，兼顾惩治与预防、公正与效率、刑罚手段与非刑罚手段的协调性。不仅关注醉酒危险驾驶犯罪的刑罚惩治，也注重因醉驾构成交通肇事罪、以危险方法危害公共安全罪等更严重犯罪的刑罚惩治。坚持综合治理，运用刑罚手段惩治醉驾的同时，也重视源头治理、综合施策，协同党政机关、行业协会、企事业单位以及公民个人，齐抓共管、群防群治，共同做好各环节的预防、治理工作。《意见》共30条，分为总体要求、立案与侦查、刑事追究、快速办理、综合治理以及附则六部分，内容全面、法网严密。其中，立案与侦查部分对立案标准、道路、机动车认定、强制措施、证据收集等作了规定；刑事追究部分对从重、从宽处理情形、情节显著轻微、情节轻微认定、量刑标准，公益服务、刑事处罚与行政处罚衔接等作了规定；快速办理部分对醉驾案件适用快速办理机制的原则、范围、期限、流程等内容作了规定。问：刚才谈到要坚持严格执法、公正司法，《意见》在这方面有哪些具体体现？答：“两高两部”紧紧围绕严格执法、公正司法这个主题，根据醉驾治理新形势新变化新要求，着力运用法治思维、法治方式破难题、解新题，系统补充完善“2013年意见”，形成标准统一、规则严密、要求明确、操作性强，行政执法与刑事司法相互衔接、梯次递进的酒驾醉驾治理体系。一是进一步统一执法司法标准。《意见》着力解决各地醉驾案件执法司法标准不够统一、处理不够均衡问题，统一行政处罚、刑事立案、起诉、量刑等标准，确保执法司法更加规范。比如，《意见》重申血液酒精含量80毫克/100毫升的醉酒标准，明确情节显著轻微、情节轻微以及一般不适用缓刑的具体标准和情形，规定罚金刑的起刑点和幅度。二是织密法网，严密规则。《意见》进一步严密醉驾治理的刑事、行政法网和规则体系，依法治理醉驾的操作性更强。比如，《意见》细化醉驾案件证据收集、审查采信规则，对于血液样本提取、封装等环节的程序性瑕疵，提出补正完善和是否采信的规则，确保不枉不纵；明确醉驾属于严重的饮酒后驾驶机动车行为，对不追究刑事责任的醉驾行为人应依法予以行政处罚。三是更加注重考量醉驾的具体情节，确保公平公正地处理案件。《意见》充分考虑醉驾的动机和目的、醉酒程度、机动车类型、道路情况、行驶时间、速度、距离、后果以及认罪悔罪表现等因素，做到该宽则宽，当严则严，罚当其罪。比如，《意见》在“2013年意见”规定的8项从重处理情形基础上，又调整、增加了醉驾校车、“毒驾”“药驾”等7项从重处理情形。问：《意见》在提升醉驾案件办理质效方面有哪些举措？答：醉驾案件案情不复杂，适用法律方面相对明确。为兼顾公正与效率，《意见》提出要因地制宜建立健全醉驾案件快速办理机制，简程序不减权利，实现案件优质高效办理。一是明确符合规定情形、适用快速办理机制的案件，一般应当在立案侦查之日起30日内完成侦、诉、审工作。二是进一步简化办案手续。规定案件移送至审查起诉或者审判阶段时，取保候审期限尚未届满且符合取保候审条件的，受案机关可以不再重新作出取保候审决定。三是明确对拟适用缓刑的人员，一般不再委托社区矫正机构或者有关社会组织进行调查评估。四是简化法律文书制作，允许采取合并式、要素式、表格式等方式制作文书，具备条件的地区还可以通过网上办案平台流转卷宗和文书。问：经过十余年的治理，仍然有一些人酒后开车。《意见》在源头预防和综合治理方面有哪些举措？答：在保持惩治酒驾醉驾力度不减的情况之下，为什么还有一些人以身试法，归根结底还是心存侥幸，守法意识淡薄。打击惩罚这一手不能放松，但“一罚了之”不是最佳方案、治本之策，源头预防、综合治理这一手不可或缺。《意见》从三方面要求加强源头预防和综合治理工作。一是加强普法宣传教育。酒驾醉驾预防宣传应当成为执法司法机关的常态化工作，要采取形式多样的宣传教育方式，引导社会公众认识到酒驾醉驾的危险性，让“喝酒不开车”的观念更加深入人心。二是加强协同治理。酒驾醉驾不仅是法律问题，更是社会治理问题。对执法司法过程中发现的酒驾醉驾治理问题，要充分运用司法建议、检察建议、提示函等机制，督促相关单位齐抓共管、群防群治。三是加强教育改造。惩前毖后、治病救人是我们党长期坚持的方针。在醉驾案件办理中，要加强对涉案人员的教育、矫正，防范再犯。最后，我们呼吁广大驾驶人员，为了您和家人的幸福，为了大家出行安全，请自觉遵守交通规则，杜绝酒后驾驶，争做守护道路交通安全的第一责任人。"""),
    )
)

val LF2_OVERLOAD_OVER_SPEED_STANDARD: LawBook = LawBook(
    id = "overload_over_speed_standard",
    name = "严重超员、严重超速危险驾驶刑事案件立案标准（试行）",
    articlesCount = 3,
    chapters = 0,
    intro = """明确从事校车业务、公路客运、旅游客运、包车客运中严重超员、严重超速，以及机动车所有人、管理人相关行为的立案侦查标准，全文收录（共3条）。""",
    articles = listOf(
        LawArticle("第一条", "", """在道路上驾驶机动车从事校车业务或者公路客运、旅游客运、包车客运，有下列严重超过额定乘员载客情形之一的，可以立案侦查：（一）驾驶大型载客汽车，载客超过额定乘员50%以上或者超过额定乘员15人以上的；（二）驾驶中型载客汽车，载客超过额定乘员80%以上或者超过额定乘员10人以上的；（三）驾驶小型、微型载客汽车，载客超过额定乘员100%以上或者超过额定乘员7人以上的。"""),
        LawArticle("第二条", "", """在道路上驾驶机动车从事校车业务或者公路客运、旅游客运、包车客运，有下列严重超过规定时速行驶情形之一的，可以立案侦查：（一）在高速公路、城市快速路上行驶，超过规定时速50%以上，且行驶时速达到90公里以上；（二）在高速公路、城市快速路以外的道路上行驶，超过规定时速100%以上，且行驶时速达到60公里以上的；（三）通过铁路道口、急弯路、窄路、窄桥或者在冰雪、泥泞的道路上行驶，或者掉头、转弯、下陡坡，以及遇雾、雨、雪、沙尘、冰雹等低能见度气象条件时，超过规定时速50%以上，且行驶时速达到30公里以上的；（四）通过傍山险路、连续下坡、连续急弯等事故易发路段，超过规定时速50%以上，且行驶时速达到30公里以上的。"""),
        LawArticle("第三条", "", """机动车所有人、管理人强迫、指使机动车驾驶人实施本标准第一条、第二条所列行为或者有其他负有直接责任情形的，可以立案侦查。"""),
    )
)

val LF2_ARTICLE52_REPLY: LawBook = LawBook(
